/// "Lady Gaga · Beyoncé" — every name tappable.
///
/// The guest credit lives wherever the ripper put it: the artist tag, the title, or — for the
/// Lady Gaga file on this machine — nowhere at all. So when the tags name nobody and [lookup] is
/// on, the catalogue is asked who else played on it.
class ArtistLine extends StatefulWidget {
  final String artist;
  final String title;
  final TextStyle style;
  final bool lookup;

  /// Doorgegeven aan [ArtistNames]; zie daar waarom dit standaard uit staat.
  final bool omvouwen;

  /// De ronde portretjes van de artiesten vóór de namen — zie [ArtiestRondjes]. Alleen op Nu speelt.
  final bool rondjes;

  /// De selectie van het eerste rondje, zodat de hoes op een tv er met OMHOOG naartoe kan.
  final FocusNode? eersteRondje;

  /// Wie er al bovenaan staat (de kop van Nu speelt, gestapeld). Dan toont deze regel alleen wie er nog
  /// bij komt — zie [gastenNaastKop] — en niets als dat niemand is. Null = iedereen, zoals overal.
  final List<String>? alNoemd;

  const ArtistLine({
    super.key,
    required this.artist,
    required this.title,
    required this.style,
    this.lookup = false,
    this.omvouwen = false,
    this.rondjes = false,
    this.eersteRondje,
    this.alNoemd,
  });

  @override
  State<ArtistLine> createState() => _ArtistLineState();
}

class _ArtistLineState extends State<ArtistLine> {
  List<String> _extra = const [];

  @override
  void initState() {
    super.initState();
    _fetch();
  }

  @override
  void didUpdateWidget(ArtistLine old) {
    super.didUpdateWidget(old);
    if (old.artist != widget.artist || old.title != widget.title) {
      setState(() => _extra = const []);
      _fetch();
    }
  }

  Future<void> _fetch() async {
    if (!widget.lookup) return;
    final local = splitFeatured(widget.artist, widget.title);
    if (local.featured.isNotEmpty) return; // the tags already say who's on it
    final artist = widget.artist, title = widget.title;
    final names = await CatalogService().trackContributors(artist, titleWithoutFeat(title));
    if (!mounted || artist != widget.artist || title != widget.title) return;
    final guests = names.where((n) => artistKey(n) != artistKey(local.main)).toList();
    if (guests.isNotEmpty) setState(() => _extra = guests);
  }

  @override
  Widget build(BuildContext context) {
    final split = splitFeatured(widget.artist, widget.title);
    final lib = context.watch<LibraryStore>();
    final namen = [lib.displayArtist(split.main), ...split.featured, ..._extra];
    if (widget.alNoemd case final al?) {
      final g = gastenNaastKop(namen, al);
      if (g.namen.isEmpty) return const SizedBox.shrink();
      final gasten = ArtistNames(names: g.namen, style: widget.style, omvouwen: widget.omvouwen);
      return !g.met
          ? gasten
          : Row(
              mainAxisSize: MainAxisSize.min,
              children: [Text('met ', style: widget.style), Flexible(child: gasten)],
            );
    }
    final regel = ArtistNames(names: namen, style: widget.style, omvouwen: widget.omvouwen);
    if (!widget.rondjes || namen.every((n) => n.trim().isEmpty)) return regel;
    // Dezelfde namen als de regel ernaast, ook de gasten die pas na het opzoeken binnenkomen: één lijst,
    // zodat een rondje nooit een andere artiest is dan de naam ernaast.
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        ArtiestRondjes(namen: namen, maat: isTv ? 22 : 28, eerste: widget.eersteRondje),
        const SizedBox(width: 10),
        Flexible(child: regel),
      ],
    );
  }
}

/// The artist line of a track row, tappable.
///
/// Every track list in the app used to print the artist as plain text, so the one place a record's
/// artist was reachable from was an album page. Wherever a name is shown it is now the way to that
/// artist — and a "A feat. B" tag becomes two names, because a guest is an artist too.
/// Clickable everywhere, but out of the remote's path on a television.
///
/// For controls that sit INSIDE something you already press. A mouse can reach a small link within
/// a big target; a remote has to stop on both, and the small one is almost never what you meant.
Widget _maybeFocusable(Widget child) => isTv ? ExcludeFocus(child: child) : child;

Widget _artistLine(({String main, List<String> featured}) who, TextStyle style) {
  final names = [if (who.main.trim().isNotEmpty) who.main.trim(), ...who.featured];
  if (names.isEmpty) return const SizedBox.shrink();
  final line = ArtistNames(names: names, style: style);
  // Every name here is its own focus stop, and this line sits inside a row of a track list. On a
  // television that turns one press-down-to-the-next-track into three or four, all the way through
  // a list that can be ten thousand rows long. The names stay clickable — ExcludeFocus takes them
  // out of the highlight's path, not out of the app.
  return isTv ? ExcludeFocus(child: line) : line;
}

/// A row of artist names, each tappable. Takes the names as-is — the caller decides who's on it.
class ArtistNames extends StatefulWidget {
  final List<String> names;
  final TextStyle style;

  /// Mag de lijst naar een tweede regel zakken in plaats van in te korten?
  ///
  /// **Standaard niet, en dat is met opzet.** In een nummerlijst heeft elke rij een vaste hoogte;
  /// een naam die daar naar twee regels loopt duwt de hele lijst uit elkaar. Daar hoort inkorten.
  ///
  /// Op het speelscherm is het andersom: daar is ruimte zat en wil je zien wie er meespelen. Drie
  /// artiesten op één regel werden daar tot puntjes teruggebracht — of erger, zie de begrenzing bij
  /// de artiestenrij van dat scherm.
  final bool omvouwen;

  const ArtistNames({
    super.key,
    required this.names,
    required this.style,
    this.omvouwen = false,
  });

  @override
  State<ArtistNames> createState() => _ArtistNamesState();
}

class _ArtistNamesState extends State<ArtistNames> {
  String? _hover;

  /// Eén naam, aantikbaar. Dezelfde vorm in beide indelingen — anders lopen ze uit elkaar.
  Widget _naam(String naam) => MouseRegion(
        cursor: SystemMouseCursors.click,
        onEnter: (_) => setState(() => _hover = naam),
        onExit: (_) => setState(() => _hover = _hover == naam ? null : _hover),
        child: Pressable(
          onPressed: () => openArtist(context, naam),
          borderRadius: BorderRadius.circular(6),
          scaleOnFocus: false,
          // Op een tv geen vak: een gekozen naam is wit en onderstreept, zoals elke andere link (Saber,
          // 17-10-2026: "alle links dezelfde stijl" — in de spelerbalk en op de albumpagina stond hier
          // nog het grijze vak).
          ringOnFocus: !isTv,
          // The name is underlined on hover; focus does the same, so a remote sees the link
          // as a link rather than as a ring around a piece of prose.
          onFocusChange: (v) => setState(() => _hover = v ? naam : null),
          child: Text(
            naam,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: _hover == naam
                ? (isTv
                    ? tvLinkStijl(widget.style, true)
                    : widget.style.copyWith(color: kFel, decoration: TextDecoration.underline))
                : widget.style,
          ),
        ),
      );

  /// Het scheidingsteken tussen twee namen.
  Widget _punt() =>
      Text(' · ', style: widget.style.copyWith(color: widget.style.color?.withValues(alpha: .5)));

  @override
  Widget build(BuildContext context) {
    final names = widget.names;
    // Omgevouwen: een `Wrap`, dus zakt de derde naam naar een tweede regel in plaats van te
    // verdwijnen. `Flexible` bestaat daar niet en hoeft ook niet — een `Wrap` meet elk kind op zijn
    // eigen breedte en breekt zelf af.
    if (widget.omvouwen) {
      // **De `LayoutBuilder` is geen omhaal.** Een kind van een `Wrap` krijgt net zo goed een
      // ONBEGRENSDE breedte mee als een niet-flexibel kind van een `Row` — dat is precies de fout
      // die dit hele scherm had. Zonder deze begrenzing zou één naam die in zijn eentje al breder is
      // dan de regel er weer dwars overheen lopen, in plaats van in te korten.
      return LayoutBuilder(builder: (context, ruimte) {
        final maxBreedte = ruimte.maxWidth.isFinite ? ruimte.maxWidth : double.infinity;
        return Wrap(
          crossAxisAlignment: WrapCrossAlignment.center,
          children: [
            for (var i = 0; i < names.length; i++) ...[
              if (i > 0) _punt(),
              ConstrainedBox(
                constraints: BoxConstraints(maxWidth: maxBreedte),
                child: _naam(names[i]),
              ),
            ],
          ],
        );
      });
    }
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        for (var i = 0; i < names.length; i++) ...[
          if (i > 0) _punt(),
          Flexible(child: _naam(names[i])),
        ],
      ],
    );
  }
}

/// [T] uit de providers, of null als er geen is (een widgettoets die alleen het nodige opzet).
T? _misschien<T>(BuildContext context, {bool luister = false}) {
  try {
    return luister ? context.watch<T>() : context.read<T>();
  } on ProviderNotFoundException {
    return null;
  }
}

/// Waar een nieuwe wachtrij heen gaat (een tik op een nummer, "Afspelen", "Hierna spelen" …): de gekozen
/// zone op afstand, of dit toestel (Saber, 21-10-2026: "Tik in de bibliotheek speelt in de gekozen zone").
Rijbediening rijVoor(BuildContext context) =>
    _misschien<GekozenZone>(context)?.opAfstand ?? context.read<PlayerStore>();

/// Move the playhead by [seconds], clamped to the track.
///
/// Clamped rather than left to the player: seeking past the end restarts the queue on some
/// backends and stalls on others, and neither is what "ten seconds forward" means.
void _nudge(Speelbron p, int seconds) {
  final total = p.duration;
  if (total.inMilliseconds <= 0) return;
  var target = p.position + Duration(seconds: seconds);
  if (target < Duration.zero) target = Duration.zero;
  if (target > total) target = total;
  p.seek(target);
}

/// The transport, wherever the music actually is.
///
/// Casting moves the remote. Every one of these controls used to speak to the local libmpv, which
/// is deliberately silent while a speaker has the queue — so on a phone steering the KEF, pause,
/// next, previous and the scrubber all appeared to do nothing while the music played on.
///
/// One place, read by the desktop bar, the phone bar and the full player alike: three copies of
/// "which player am I talking to" is three chances for one of them to be wrong.
///
/// Sinds de zones (Saber, 21-10-2026) ook een zone op afstand: is er een gekozen ("Speelt op: … ▾"), dan is
/// [player] die zone ([ZoneSpeler]) en sturen alle knoppen haar. [lokaal] is altijd de speler van dit
/// toestel.
class _Transport {
  _Transport(BuildContext context)
      : lokaal = context.watch<PlayerStore>(),
        speaker = context.watch<SpeakerTarget>(),
        afstand = _misschien<GekozenZone>(context, luister: true)?.opAfstand;

  final PlayerStore lokaal;
  final SpeakerTarget speaker;

  /// De gekozen zone op afstand, of null: dan is het dit toestel.
  final ZoneSpeler? afstand;

  /// Wie de knoppen krijgen: de gekozen zone, of de speler van dit toestel.
  Speelbron get player => afstand ?? lokaal;

  /// Cast dit toestel naar een speaker? Niet als er een zone op afstand gekozen is: die cast zelf.
  bool get casting => afstand == null && speaker.isCasting;
  Track? get track => player.current;

  /// Position and length come from the SPEAKER while casting — it is the only one that knows.
  Duration get position => casting ? (speaker.position ?? Duration.zero) : player.position;
  Duration get duration => casting ? (speaker.duration ?? Duration.zero) : player.duration;
  bool get playing => casting ? speaker.isPlaying : player.playing;

  double get progress => duration.inMilliseconds == 0
      ? 0.0
      : (position.inMilliseconds / duration.inMilliseconds).clamp(0.0, 1.0);

  bool get canSeek => duration.inMilliseconds > 0 && (casting || track != null);

  VoidCallback? get playPause => casting
      ? () => unawaited(speaker.playPause())
      : (track == null ? null : player.playPause);

  /// Bij twijfel de eigen wachtrij, niet grijs.
  ///
  /// `hasNext` eist dat de speaker zowel zijn index als de lengte meldt, en `hasPrev` leest een
  /// ontbrekende index als nul. Zwijgt de status even -- een sessie die net is afgelopen, een speaker
  /// die één poll niet antwoordt -- dan vielen beide knoppen dood terwijl de muziek gewoon doorliep.
  /// Dat is wat "de app verliest de controle" was.
  ///
  /// Sinds de overdracht teruggeeft welke nummers de speaker gekregen heeft, is de wachtrij hier
  /// dezelfde lijst met dezelfde nummering. De app weet dus zelf of er een volgende is, en dat is een
  /// beter antwoord dan een grijze knop. Een druk die de speaker niet kan uitvoeren doet niets; een
  /// knop die niet ingedrukt kan worden doet ook niets, maar leest als een defect.
  VoidCallback? get next => casting
      ? ((speaker.status?.hasNext ?? player.hasNext) ? () => unawaited(speaker.next()) : null)
      : (player.hasNext ? player.next : null);

  /// Below three seconds, "previous" means the previous track; after that it means this one again.
  /// That is a local nicety and stays local: the speaker is told plainly which track to play.
  VoidCallback? get previous => casting
      ? ((speaker.status?.hasPrev ?? player.hasPrev) ? () => unawaited(speaker.previous()) : null)
      : (player.hasPrev || player.position > const Duration(seconds: 3) ? player.prev : null);

  /// While the finger moves. Carried locally when casting and sent once on release — a seek per
  /// pixel would flood an embedded UPnP stack and land behind where you let go.
  void scrub(double fraction) =>
      casting ? speaker.scrubTo(duration * fraction) : player.seek(duration * fraction);

  void seekEnd(double fraction) {
    if (casting) unawaited(speaker.seekTo(duration * fraction));
  }

  /// Ten seconds either way, for a remote — and for a speaker, the only seek that needs no slider.
  void nudge(int seconds) {
    if (!casting) return _nudge(player, seconds);
    final total = duration;
    if (total.inMilliseconds <= 0) return;
    var target = position + Duration(seconds: seconds);
    if (target < Duration.zero) target = Duration.zero;
    if (target > total) target = total;
    unawaited(speaker.seekTo(target));
  }
}

// ── Now-playing bar ──────────────────────────────────────────────────────────
/// Hoe breed de knoppen in het midden van de brede spelerbalk hoogstens zijn: shuffle, vorige,
/// afspelen, volgende, herhalen, wachtrij, speaker en "Speel op …" — acht van 48 plus de tussenruimte.
const double kSpelerKnoppen = 8 * 48 + 8;

/// Het vak links (het nummer) en rechts ("Verder op …") van de brede spelerbalk; wat overblijft is
/// voor de knoppen.
///
/// **Waarom uitgerekend (18-10-2026).** Dit was `(breedte - 336) / 2`, zonder de randen van de balk en
/// met minder knoppen dan er staan. Op de Shield (960 punten, 48 overscan aan elke kant) bleef er zo
/// 268 over voor 340 aan knoppen: ze liepen aan beide kanten het vak in. Zolang het rechtervak leeg
/// was zag je dat niet; met "Verder op …" erin lag de wachtrijknop half en de speakerknop helemaal
/// eronder.
@visibleForTesting
double spelerZijvak(double breedte, {required double rand}) =>
    math.min(280.0, math.max(96.0, (breedte - rand - kSpelerKnoppen) / 2));

class PlayerBar extends StatelessWidget {
  const PlayerBar({super.key, this.metSysteeminzet = true, this.opGlas = false});

  /// Ligt deze balk op glas ([metGlasBalken])? Dan is zijn kleur doorschijnend.
  final bool opGlas;

  /// Houdt deze balk zélf ruimte vrij voor de systeembalk onderaan?
  ///
  /// Alleen de ONDERSTE widget van een scherm hoort dat te doen. Op de albumpagina, de
  /// artiestpagina en de wachtrij is deze balk dat, dus daar blijft het aan. In het hoofdscherm
  /// staat er sinds de navigatiebalk iets ONDER hem, en [Onderbalk] houdt die ruimte zelf al vrij
  /// — hij stond er dus twee keer op. Dat is de lege band tussen de speler en de pictogrammen, en
  /// de reden dat de onderbalk te hoog aanvoelde.
  final bool metSysteeminzet;

  @override
  Widget build(BuildContext context) {
    // Op glas hangt de kleur aan de glasstand ([balkOpGlas]): zet de bewaker het glas plat, dan gaat
    // de vervaging eronder weg en moet de balk dicht worden. Maar deze balk staat als `const` in de
    // glasbalken en werd bij die wissel niet opnieuw gebouwd: doorschijnend zonder vervaging, en de
    // tekst van de pagina leesbaar dwars door de titel (gsm, 18-10-2026).
    if (opGlas) {
      return ValueListenableBuilder<GlasStand>(
          valueListenable: GlasKwaliteit.stand, builder: (context, _, __) => _bouw(context));
    }
    return _bouw(context);
  }

  Widget _bouw(BuildContext context) {
    final x = _Transport(context);
    final p = x.player;
    final t = x.track;
    // Under the home indicator on an iPad: the bar's colour runs to the bottom edge, its contents
    // stop above the bar the system draws over everything.
    final bottomInset =
        _isTouch && metSysteeminzet ? MediaQuery.viewPaddingOf(context).bottom : 0.0;
    // 280 a side in a desktop window, which is what centres the transport controls. Two of those
    // plus the controls do not fit on an iPad in portrait — 596 of 834 points gone before the
    // buttons start — so they give way instead of overflowing.
    final width = MediaQuery.sizeOf(context).width;

    // A phone gets a different bar entirely, not a squeezed one.
    //
    // The desktop bar reserves a side block for the track and centres the transport in what is
    // left. At 411 points that block bottoms out at its 96-point floor, of which the cover takes 54
    // and the gap 12 — leaving thirty points for the title, which printed "Niets aan het spelen"
    // one letter per line and overflowed the bar by 45 pixels.
    if (isCompact(context)) return _compactBar(context, x, bottomInset, opGlas: opGlas);

    final side = spelerZijvak(width, rand: 36 + tvOverscan.horizontal);
    return AnimatedContainer(
      // Overvloeien en niet omslaan: deze balk staat permanent in beeld, en een kleur die per nummer
      // omspringt trekt aandacht op de plek waar je juist niet kijkt.
      duration: kWas,
      curve: Curves.easeOut,
      // Taller on a television: the text is scaled there, and the bottom row (position, slider,
      // duration) sat flush against the panel edge — the first strip a set overscans away.
      height: (isTv ? 104 : 84) + bottomInset,
      // Op glas doorschijnend en zonder streep: de lichtrand van het glas is de bovenrand. Op een tv in
      // het lichte thema de kleur van dat glas, ook zonder streep ([balkOpTvLicht]).
      decoration: BoxDecoration(
        color: opGlas
            ? balkOpGlas(x.player.wasKleur)
            : isTv && Thema.licht
                ? balkOpTvLicht(x.player.wasKleur)
                : balkKleur(x.player.wasKleur),
        border: opGlas || (isTv && Thema.licht) ? null : Border(top: BorderSide(color: _line)),
      ),
      // The panel runs to the edge; only what you read and press comes in. On a television the
      // bottom row of this bar is the first thing a set overscans away, so it gets tvOverscan
      // rather than the 0 it had — SafeArea is no help here, a TV reports no insets at all.
      padding: EdgeInsets.fromLTRB(
          18 + tvOverscan.left, 0, 18 + tvOverscan.right, bottomInset + tvOverscan.bottom),
      // De kleurvlekken van de hoes, boven de kleur van de balk en onder de knoppen (Saber,
      // 18-10-2026). Ze lopen door tot in de binnenmarge, tot de rand van de balk.
      child: CustomPaint(
        painter: HoesVlekkenSchilder(p.hoesVlekken,
            uitloop: EdgeInsets.fromLTRB(
                18 + tvOverscan.left, 0, 18 + tvOverscan.right, bottomInset + tvOverscan.bottom)),
        child: Row(
        children: [
          SizedBox(
            width: side,
            child: Row(
              children: [
                Pressable(
                  // Null while nothing plays, which also stops the highlight from resting on a
                  // cover that opens nothing.
                  onPressed: t == null
                      ? null
                      // Zie `naarNuSpeelt`: dit scherm bedekt met opzet álles, en is het enige
                      // dat dat nog doet.
                      : () => Navigator.of(context, rootNavigator: true).push(nuSpeeltRoute()),
                  borderRadius: BorderRadius.circular(8),
                  child: MouseRegion(
                    cursor: t == null ? MouseCursor.defer : SystemMouseCursors.click,
                    child: cover(p.currentCover, size: 54, radius: 8),
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  // Een ander nummer: titel en artiest schuiven weg en de nieuwe schuiven binnen.
                  child: SchuifTekst(
                  sleutel: t?.path,
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(
                        children: [
                          Flexible(
                            child: Text(t?.title ?? '—',
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(fontWeight: FontWeight.w600)),
                          ),
                          // Het hart: vol als het een favoriet is, en het klopt als het er een wordt.
                          if (t != null && !isTv) _HartKnop(track: t),
                          // 👍 "houden" bij een nummer dat de radio haalde, ook als hij op een speaker speelt — zie
                          // [_radioHier]. Alleen omhoog: zie [_RijDuimen.alleenHouden].
                          if (t != null && !isTv && _radioHier(context)) _RijDuimen(track: t, alleenHouden: true, maat: 26),
                          // What quality am I actually hearing? (local files only — a streamed
                          // source's real quality isn't known here.)
                          //
                          // NIET OP EEN TELEVISIE. Deze twee staan niet in de flex, dus ze krijgen
                          // hun volle breedte en de titel houdt over wat er rest. Op een pc is dat
                          // ruim; op een tv is dit blok 280 punten breed, waarvan de hoes en de tussen-
                          // ruimte er 66 nemen, en bij de tekstschaal van 1,35 die een tv krijgt vullen
                          // "24/44.1" en "FLAC · 24/192" samen de rest. Gemeten op de Shield: de titel
                          // werd naar nul geknepen, en in de balk stond alleen nog de artiest met twee
                          // getallen erboven. Van drie meter afstand is de titel juist het enige wat
                          // telt -- en de kwaliteit staat voluit op het nu-speelt-scherm, één knop weg.
                          if (t != null && !isTv) _echtheidMerk(t),
                          if (t != null && !isTv && t.sizeBytes > 0)
                            _qualityBadge(_trackQuality(t)),
                        ],
                      ),
                      // Een klacht gaat vóór de artiestnaam. Wie hier kijkt omdat er geen geluid
                      // komt, wil weten waaróm — de naam staat er toch al boven.
                      if (p.speelFout != null)
                        Text(p.speelFout!,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(color: leesbaar(const Color(0xFFE0A33A)), fontSize: 12.5))
                      else if ((p.radioMode ? _radioRegel(context, p) : null) case final s?)
                        Text(s,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(color: _accent2, fontSize: 12.5))
                      else if (t == null)
                        Text('Niets aan het spelen',
                            style: TextStyle(color: _muted, fontSize: 12.5))
                      // Een herhaling vervangt de artiest niet: "opnieuw" komt erachter.
                      else if (p.speeltHerhaling)
                        Row(children: [
                          Flexible(
                            child: ArtistLine(
                              artist: t.artist,
                              title: t.title,
                              lookup: true,
                              style: TextStyle(color: _muted, fontSize: 12.5),
                            ),
                          ),
                          Text(' · opnieuw', style: TextStyle(color: _accent2, fontSize: 12.5)),
                        ])
                      else
                        // Everyone on the track, each name tappable — a guest artist is exactly
                        // who you want to look up while their verse is playing.
                        ArtistLine(
                          artist: t.artist,
                          title: t.title,
                          lookup: true,
                          style: TextStyle(color: _muted, fontSize: 12.5),
                        ),
                    ],
                  ),
                  ),
                ),
              ],
            ),
          ),
          Expanded(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    // Shuffle and repeat are the two you reach for least, and on a phone the row
                    // has to hold a rewind and a forward besides. They are on the full player,
                    // which is one tap away.
                    if (!isCompact(context))
                    IconButton(
                      // Klapt even om als hij aan gaat (Saber, 17-10-2026). Zie ui/knopbewegingen.dart.
                      icon: ShuffleIcoon(aan: p.shuffle, maat: 20),
                      color: p.shuffle ? _accent : _muted,
                      style: tvIcoonStijl(p.shuffle ? _accent : _muted),
                      onPressed: p.toggleShuffle,
                    ),
                    DuwKnop(
                      icoon: Icons.skip_previous_rounded,
                      richting: -1,
                      kleur: _muted,
                      style: tvIcoonStijl(_muted),
                      onPressed: x.previous,
                    ),
                    // Geen ±10-knoppen meer op een tv (Saber, 16-10-2026: "te druk"). Spoelen doe je
                    // in Nu speelt door links of rechts ingedrukt te houden op de hoes (SpoelPijlen).
                    const SizedBox(width: 2),
                    Container(
                      decoration: BoxDecoration(color: kFel, shape: BoxShape.circle),
                      child: IconButton(
                        // Het driehoekje vloeit over in de twee streepjes, en terug.
                        icon: SpeelPauzeIcoon(speelt: x.playing, maat: 26),
                        color: _bg,
                        style: tvIcoonStijl(_bg),
                        iconSize: 26,
                        onPressed: x.playPause,
                      ),
                    ),
                    const SizedBox(width: 2),
                    DuwKnop(
                      icoon: Icons.skip_next_rounded,
                      kleur: _muted,
                      style: tvIcoonStijl(_muted),
                      onPressed: x.next,
                    ),
                    if (!isCompact(context))
                    IconButton(
                      icon: HerhaalIcoon(
                          stand: p.repeat,
                          icoon: p.repeat == RepeatMode.one ? Icons.repeat_one_rounded : Icons.repeat_rounded,
                          maat: 20),
                      color: p.repeat == RepeatMode.off ? _muted : _accent,
                      style: tvIcoonStijl(p.repeat == RepeatMode.off ? _muted : _accent),
                      // Local only: the speaker is handed one track at a time, so a change here
                      // would take effect on whatever is sent next and look like it did nothing.
                      onPressed: x.casting ? null : p.cycleRepeat,
                    ),
                    const _WachtrijKnop(),
                    const _SpeakerButton(),
                    // De zones (Saber, 21-10-2026). Daarin ook "Speel daar" — vroeger "Speel op …".
                    if (!isTv) const ZoneKiesKnop(alsIcoon: true),
                  ],
                ),
                Row(
                  children: [
                    Text(_fmt(x.position), style: TextStyle(color: _muted, fontSize: 11.5)),
                    Expanded(
                      child: SliderTheme(
                        data: SliderTheme.of(context).copyWith(
                          trackHeight: 4,
                          thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 6),
                          overlayShape: const RoundSliderOverlayShape(overlayRadius: 12),
                          activeTrackColor: _accent,
                          inactiveTrackColor: kLijn,
                          thumbColor: kFel,
                        ),
                        child: _maybeFocusable(Slider(
                          value: x.progress,
                          onChanged: x.canSeek ? x.scrub : null,
                          onChangeEnd: x.casting && x.canSeek ? x.seekEnd : null,
                        )),
                      ),
                    ),
                    Text(_fmt(x.duration), style: TextStyle(color: _muted, fontSize: 11.5)),
                  ],
                ),
              ],
            ),
          ),
          // The mirror of the leading block: it is what keeps the transport in the middle. En de plek
          // van "Verder op …" (Saber, 18-10-2026): bedekt niets en is altijd te vinden.
          SizedBox(
            width: side,
            child: const Align(alignment: Alignment.centerRight, child: VerderKnop()),
          ),
        ],
      ),
      ),
    );
  }

}

/// Het icoon van een soort zone.
IconData zoneIcoon(ZoneSoort s) => switch (s) {
      ZoneSoort.pc => Icons.desktop_windows_rounded,
      ZoneSoort.mac => Icons.laptop_mac_rounded,
      ZoneSoort.gsm => Icons.smartphone_rounded,
      ZoneSoort.tablet => Icons.tablet_mac_rounded,
      ZoneSoort.tv => Icons.tv_rounded,
      ZoneSoort.speaker => Icons.speaker_rounded,
    };

/// "Speelt op: … ▾" (Saber, 21-10-2026): bovenaan Nu speelt, en als icoon in de brede spelerbalk. Opent
/// het [ZoneBlad]: wat elk toestel en elke speaker speelt, met "Hier verder" vanaf elke zone. Er staat
/// een stipje bij zodra er ergens anders iets speelt.
///
/// Onzichtbaar zolang de pc geen zones kent (een pc van vóór 3.9.546): dan blijft alleen de balk "Hier
/// verder luisteren" zoals hij was.
class ZoneKiesKnop extends StatelessWidget {
  const ZoneKiesKnop({super.key, this.alsIcoon = false});

  final bool alsIcoon;

  @override
  Widget build(BuildContext context) {
    final z = context.watch<ZoneLijst>();
    if (!z.ondersteund) return const SizedBox.shrink();
    final afstand = _misschien<GekozenZone>(context, luister: true)?.opAfstand;
    final gekozen = afstand?.zone ?? z.dezeZone;
    // Het stipje: er speelt iets in een zone die je nu NIET voor je hebt.
    final elders = z.zones.any((x) => x.playing && x.id != (afstand?.zoneId ?? z.hier)) ||
        // Of er is iets om hier verder te luisteren (het stipje dat vroeger op het verder-icoon stond).
        (afstand == null && _misschien<VerderLuisteren>(context, luister: true)?.aanbod != null);
    final stip = Positioned(
      right: -2,
      top: -2,
      child: Container(
        width: 8,
        height: 8,
        decoration: BoxDecoration(color: _accent2, shape: BoxShape.circle),
      ),
    );
    if (alsIcoon) {
      return IconButton(
        key: const ValueKey('zone-knop'),
        tooltip: elders ? 'Zones — er speelt ook iets op een ander toestel' : 'Zones',
        onPressed: () => toonZoneBlad(context),
        icon: Stack(clipBehavior: Clip.none, children: [
          Icon(Icons.speaker_group_rounded, size: 20, color: afstand != null ? _accent2 : _muted),
          if (elders) stip,
        ]),
      );
    }
    final naam = gekozen?.naam ?? deviceName();
    // Op afstand in de accentkleur: wat je ziet en bedient, is niet dit toestel.
    final kleur = afstand != null ? _accent2 : _muted;
    return Pressable(
      key: const ValueKey('zone-kies'),
      onPressed: () => toonZoneBlad(context),
      borderRadius: BorderRadius.circular(999),
      scaleOnFocus: false,
      vastePlek: false,
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          Stack(clipBehavior: Clip.none, children: [
            Icon(zoneIcoon(gekozen?.soort ?? (isCompact(context) ? ZoneSoort.gsm : ZoneSoort.pc)),
                size: 16, color: kleur),
            if (elders) stip,
          ]),
          const SizedBox(width: 6),
          Flexible(
            child: Text('Speelt op: $naam',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(color: kleur, fontSize: 12.5, fontWeight: FontWeight.w600)),
          ),
          Icon(Icons.arrow_drop_down_rounded, size: 20, color: kleur),
        ]),
      ),
    );
  }
}

/// Het [ZoneBlad] van onderen.
Future<void> toonZoneBlad(BuildContext context) => showModalBottomSheet<void>(
      context: context,
      backgroundColor: Colors.transparent,
      isScrollControlled: true,
      builder: (_) => const ZoneBlad(),
    );

/// Alle zones: wat er op elk toestel en elke speaker speelt, waar in het nummer, en of het toestel er
/// is. Vanaf elke zone "Hier verder" (de wachtrij, de plek in het nummer, shuffle en herhalen, of de
/// radio; dat toestel pauzeert). Op de pc daarnaast "Speel daar": wat de pc speelt, naar een toestel
/// waarop de app open staat — vroeger "Speel op …" in de spelerbalk.
///
/// Deelstap 2.1 van de zones: zien en overnemen. Een zone kiezen en bedienen komt erna.
class ZoneBlad extends StatefulWidget {
  const ZoneBlad({super.key});

  @override
  State<ZoneBlad> createState() => _ZoneBladState();
}

class _ZoneBladState extends State<ZoneBlad> {
  // De plek in een nummer dat ergens anders speelt, schuift elke seconde op.
  late final Timer _tik = Timer.periodic(const Duration(seconds: 1), (_) {
    if (mounted) setState(() {});
  });

  @override
  void dispose() {
    _tik.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final z = context.watch<ZoneLijst>();
    final zones = z.zones;
    final gekozen = _misschien<GekozenZone>(context, luister: true)?.gekozen ?? z.hier;
    final hoog = MediaQuery.sizeOf(context).height;
    return SafeArea(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
        child: ConstrainedBox(
          constraints: BoxConstraints(maxWidth: 600, maxHeight: hoog * .8),
          child: GlasVlak(
            vorm: const BorderRadius.all(Radius.circular(18)),
            kleur: _panel,
            balk: true,
            bovenop: true,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(14, 14, 8, 10),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(children: [
                    const Expanded(
                      child: Text('Zones', style: TextStyle(fontSize: 17, fontWeight: FontWeight.w700)),
                    ),
                    if (!z.verbonden)
                      Padding(
                        padding: const EdgeInsets.only(right: 8),
                        child: Text('Even geen verbinding met de pc',
                            style: TextStyle(color: _muted, fontSize: 11.5)),
                      ),
                  ]),
                  const SizedBox(height: 2),
                  Text('Tik op een zone om ze hier te zien en te bedienen',
                      style: TextStyle(color: _muted, fontSize: 12)),
                  const SizedBox(height: 10),
                  Flexible(
                    child: ListView(
                      shrinkWrap: true,
                      padding: EdgeInsets.zero,
                      children: [
                        for (final zone in zones)
                          _ZoneRij(
                              key: ValueKey('zone-${zone.id}'),
                              zone: zone,
                              hier: zone.id == z.hier,
                              gekozen: zone.id == gekozen),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _ZoneRij extends StatelessWidget {
  const _ZoneRij({super.key, required this.zone, required this.hier, this.gekozen = false});

  final ZoneStaat zone;
  final bool hier;

  /// Is dit de zone die je nu ziet en bedient ([GekozenZone])?
  final bool gekozen;

  @override
  Widget build(BuildContext context) {
    final lijst = context.read<ZoneLijst>();
    final verder = context.read<VerderLuisteren>();
    final nummer = zone.speeltIets ? verder.bron.nummer(zone.trackId) : null;
    final hoes = context.select<LibraryStore, Uint8List?>((l) => nummer == null ? null : l.coverForTrack(nummer));
    final nuPc = lijst.nuOpPc();
    final titel = nummer?.title ?? zone.titel;
    final artiest = nummer?.artist ?? zone.artiest;

    final kop = [
      zone.naam,
      if (hier) 'dit toestel',
      if (zone.via.isNotEmpty) 'via ${zone.via}',
    ].join(' · ');
    final String regel;
    final String? tijd;
    if (!zone.speeltIets) {
      regel = zone.online ? 'Speelt niets' : 'Niet bereikbaar';
      tijd = null;
    } else {
      regel = artiest.isEmpty ? titel : '$titel — $artiest';
      final plek = positieNu(zone, nuMs: nuPc);
      final geleden = Duration(milliseconds: (nuPc - zone.opMs).clamp(0, 1 << 40));
      tijd = [
        zone.playing ? 'Speelt' : 'Gepauzeerd',
        if (zone.radio.isNotEmpty) 'radio ${zone.radio}',
        zone.durationMs > 0 ? '${_fmt(plek)} / ${_fmt(Duration(milliseconds: zone.durationMs))}' : _fmt(plek),
        if (!zone.playing && geleden > const Duration(minutes: 1)) _geleden(geleden),
        if (!zone.online) 'niet bereikbaar',
      ].join(' · ');
    }

    Widget? actie;
    if (!hier && zone.speeltIets && zone.toestel != null) {
      // Overnemen kan van elk toestel, ook een dat weg is: zijn laatste stand staat op de pc.
      actie = GlasKnop(
        key: ValueKey('zone-verder-${zone.id}'),
        icoon: Icons.play_arrow_rounded,
        label: 'Hier verder',
        onPressed: () => _neemOverVan(context, zone),
      );
    } else if (!hier && zone.online && zone.toestel != null && lijst.opDePc) {
      final p = context.read<PlayerStore>();
      if (p.current != null) {
        actie = GlasKnop(
          key: ValueKey('zone-daar-${zone.id}'),
          icoon: Icons.cast_rounded,
          label: 'Speel daar',
          onPressed: () => _speelOpToestel(context, zone.toestel!, zone.naam),
        );
      }
    }

    return Pressable(
      key: ValueKey('zone-kies-${zone.id}'),
      // Kiezen: de balk en Nu speelt tonen en bedienen vanaf nu deze zone. De muziek verhuist niet.
      onPressed: () {
        _misschien<GekozenZone>(context)?.kies(zone.id);
        Navigator.of(context).maybePop();
      },
      borderRadius: BorderRadius.circular(10),
      scaleOnFocus: false,
      vastePlek: false,
      child: Opacity(
      opacity: zone.online || hier ? 1 : .55,
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 6, horizontal: 4),
        child: Row(children: [
          SizedBox(
            width: 46,
            height: 46,
            child: hoes != null
                ? cover(hoes, size: 46, radius: 8)
                : DecoratedBox(
                    decoration: BoxDecoration(color: _panel2, borderRadius: BorderRadius.circular(8)),
                    child: Icon(zoneIcoon(zone.soort), size: 22, color: _muted),
                  ),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(children: [
                  Icon(zoneIcoon(zone.soort), size: 13, color: zone.playing ? _accent2 : _muted),
                  const SizedBox(width: 5),
                  Flexible(
                    child: Text(kop,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(
                            color: zone.playing ? _accent2 : _muted, fontSize: 11.5, fontWeight: FontWeight.w600)),
                  ),
                ]),
                const SizedBox(height: 2),
                Text(regel,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(fontSize: 13.5, fontWeight: FontWeight.w600)),
                if (tijd != null)
                  Text(tijd,
                      maxLines: 1, overflow: TextOverflow.ellipsis, style: TextStyle(color: _muted, fontSize: 11.5)),
              ],
            ),
          ),
          if (actie != null) ...[const SizedBox(width: 8), actie],
          // Samen laten spelen (stap 3.1): Sonossen, op de seconde gelijk.
          if (zone.kanGroeperen && lijst.stuur != null)
            IconButton(
              key: ValueKey('zone-groep-${zone.id}'),
              tooltip: zone.groep.isEmpty ? 'Samen laten spelen …' : 'Groep aanpassen …',
              icon: Icon(Icons.link_rounded, size: 20, color: zone.groep.isEmpty ? _muted : _accent2),
              onPressed: () => _kiesGroep(context, zone),
            ),
          // Overdragen naar een andere zone (stap 2.5): de muziek verhuist, deze zone pauzeert.
          if (zone.speeltIets && lijst.verplaats != null)
            IconButton(
              key: ValueKey('zone-naar-${zone.id}'),
              tooltip: 'Verplaats naar …',
              icon: Icon(Icons.move_down_rounded, size: 20, color: _muted),
              onPressed: () => _kiesDoelZone(context, zone),
            ),
          if (gekozen)
            Padding(
              padding: const EdgeInsets.only(left: 8),
              child: Icon(Icons.check_rounded, size: 20, color: _accent2, semanticLabel: 'gekozen'),
            ),
          const SizedBox(width: 4),
        ]),
      ),
      ),
    );
  }

  static String _geleden(Duration d) => d.inHours >= 1
      ? '${d.inHours} u geleden'
      : '${d.inMinutes} min geleden';
}

/// Het volume van de app in een zone op afstand (Saber, 21-10-2026: "volume van de app"). De schuif
/// stuurt hoogstens vier keer per seconde, en de laatste stand komt altijd aan ([ZoneSpeler.setVolume]).
class _ZoneVolume extends StatelessWidget {
  const _ZoneVolume({required this.zone});

  final ZoneSpeler zone;

  @override
  Widget build(BuildContext context) {
    final v = zone.volume.clamp(0, 100).toDouble();
    return Row(
      key: const ValueKey('zone-volume'),
      children: [
        Icon(Icons.volume_down_rounded, size: 19, color: _muted),
        Expanded(
          child: SliderTheme(
            data: SliderTheme.of(context).copyWith(
              trackHeight: 3,
              thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 6),
              activeTrackColor: _accent,
              inactiveTrackColor: kLijn,
              thumbColor: kFel,
            ),
            child: Slider(value: v, max: 100, onChanged: zone.setVolume),
          ),
        ),
        Icon(Icons.volume_up_rounded, size: 19, color: _muted),
        const SizedBox(width: 6),
        SizedBox(
          width: 30,
          child: Text('${v.round()}', textAlign: TextAlign.right, style: TextStyle(color: _muted, fontSize: 12)),
        ),
      ],
    );
  }
}

/// "Samen laten spelen …" (stap 3.1–3.3, Saber 21-10-2026: "Sonos onderling", "gsm/iPad/Mac/pc samen",
/// "pc + Sonos ongeveer, met een schuif"): vink aan wie met [leider] meespeelt.
///
/// - Sonossen onderling lopen op de seconde gelijk: dat doen de Sonossen zelf.
/// - Toestellen volgen de leider en sturen bij (`samen.dart`).
/// - Een Sonos met toestellen: de Sonos wordt de leider (hij laat zich niet bijsturen) en de toestellen
///   volgen hem — ongeveer, want hij meldt zijn plek per seconde; de schuif "Sonos gelijkzetten" zet het op
///   het oor gelijk. Komt de groep van een toestel, dan speelt de Sonos verder wat dat toestel speelde.
Future<void> _kiesGroep(BuildContext context, ZoneStaat leider) async {
  final lijst = context.read<ZoneLijst>();
  final gekozen = _misschien<GekozenZone>(context);
  final speaker = leider.soort == ZoneSoort.speaker;
  // Speakers onderling alleen Sonossen (die lopen samen op de seconde gelijk); toestellen met elke speaker.
  final kandidaten = [
    for (final z in lijst.zones)
      if (z.id != leider.id &&
          z.kanGroeperen &&
          z.online &&
          (z.soort != ZoneSoort.speaker || !speaker || (leider.sonos && z.sonos)))
        z,
  ];
  bool isSonos(String id) => kandidaten.where((z) => z.id == id).map((z) => z.sonos).firstOrNull ?? true;
  // Wie al in de groep zit, staat niet apart in de lijst: die halen we uit de groep zelf, en hun namen uit
  // de naam van de groep ("Sonos Move + THUIS": de leider, dan de anderen in de volgorde van de groep).
  final inGroep = {...leider.groep}..remove(leider.id);
  final keuze = {...inGroep};
  final delen = leider.naam.split(' + ');
  final volgorde = [leider.id, ...leider.groep.where((g) => g != leider.id)];
  final uitNaam = {
    if (delen.length == volgorde.length)
      for (var i = 0; i < delen.length; i++) volgorde[i]: delen[i],
  };
  final eigenNaam = delen.first;
  // Speakers eerst: komt de groep van een toestel, dan wordt de eerste aangevinkte Sonos de leider.
  final alle = {for (final z in kandidaten) z.id, ...inGroep};
  final ids = [
    for (final id in alle)
      if (id.startsWith('spk:')) id,
    for (final id in alle)
      if (!id.startsWith('spk:')) id,
  ];
  String naamVan(String id) =>
      kandidaten.where((z) => z.id == id).map((z) => z.naam).firstOrNull ??
      uitNaam[id] ??
      (id.startsWith('spk:') ? 'Speaker' : 'Toestel');
  ZoneSoort soortVan(String id) => id.startsWith('spk:')
      ? ZoneSoort.speaker
      : kandidaten.where((z) => z.id == id).map((z) => z.soort).firstOrNull ?? ZoneSoort.gsm;
  // Een Sonos met toestellen: de schuif hoort bij die Sonos.
  bool gemengd(Set<String> k) =>
      (speaker || k.any((id) => id.startsWith('spk:'))) &&
      (!speaker || k.any((id) => id.startsWith('dev:')));
  // Bestaat de groep al, dan schuift de schuif meteen (op het oor, terwijl het speelt).
  final bestaatAl = speaker && inGroep.any((id) => id.startsWith('dev:'));
  var vertraging = leider.samenMs;
  void schuifNu(Set<String> k) {
    if (bestaatAl && setEquals(k, inGroep)) {
      unawaited(lijst.stuur?.call(leider.id, {'cmd': 'samenVertraging', 'ms': vertraging}));
    }
  }

  final ok = await showModalBottomSheet<bool>(
    context: context,
    backgroundColor: Colors.transparent,
    isScrollControlled: true,
    builder: (ctx) => StatefulBuilder(
      builder: (ctx, zet) => SafeArea(
        child: Padding(
          padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 480),
            child: GlasVlak(
              vorm: const BorderRadius.all(Radius.circular(18)),
              kleur: _panel,
              balk: true,
              bovenop: true,
              child: Padding(
                padding: const EdgeInsets.fromLTRB(14, 14, 14, 10),
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text('Samen laten spelen met $eigenNaam',
                          style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w700)),
                      const SizedBox(height: 2),
                      Text(
                          speaker
                              ? 'Sonossen spelen op de seconde gelijk met deze. Toestellen volgen hem ongeveer: zet '
                                  'het op het oor gelijk met de schuif.'
                              : 'Ze volgen dit toestel. Kies je een Sonos, dan speelt die verder wat hier speelt en '
                                  'volgen de toestellen hem. Klinkt een toestel achter (Bluetooth)? Zet het bij in '
                                  'Instellingen op dat toestel: "Vertraging bij samen spelen".',
                          style: TextStyle(color: _muted, fontSize: 12)),
                      const SizedBox(height: 8),
                      if (ids.isEmpty)
                        Padding(
                          padding: const EdgeInsets.symmetric(vertical: 12),
                          child: Text('Niets gevonden om mee samen te spelen.',
                              style: TextStyle(color: _muted, fontSize: 13)),
                        ),
                      for (final id in ids)
                        CheckboxListTile(
                          key: ValueKey('zone-groep-lid-$id'),
                          value: keuze.contains(id),
                          contentPadding: EdgeInsets.zero,
                          controlAffinity: ListTileControlAffinity.leading,
                          secondary: Icon(zoneIcoon(soortVan(id)), size: 20, color: _muted),
                          title: Text(naamVan(id), style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600)),
                          onChanged: (v) => zet(() {
                            if (v != true) {
                              keuze.remove(id);
                              return;
                            }
                            // Meer dan één speaker kan alleen als het allemaal Sonossen zijn.
                            if (id.startsWith('spk:')) {
                              keuze.removeWhere((k) => k.startsWith('spk:') && (!isSonos(k) || !isSonos(id)));
                            }
                            keuze.add(id);
                          }),
                        ),
                      if (gemengd(keuze)) ...[
                        const SizedBox(height: 6),
                        Row(children: [
                          const Expanded(
                            child: Text('Sonos gelijkzetten',
                                style: TextStyle(fontSize: 13, fontWeight: FontWeight.w600)),
                          ),
                          Text(vertraging == 0 ? 'gelijk' : '${vertraging > 0 ? '+' : ''}$vertraging ms',
                              style: TextStyle(color: _muted, fontSize: 12)),
                        ]),
                        Text(
                            'Klinkt de Sonos ná de toestellen, schuif naar rechts; ervoor, naar links. Hij meldt '
                            'zijn plek per seconde: dit zet het op het oor gelijk.',
                            style: TextStyle(color: _muted, fontSize: 12)),
                        Row(children: [
                          IconButton(
                            key: const ValueKey('zone-samen-min'),
                            tooltip: '10 ms eerder',
                            icon: const Icon(Icons.remove_rounded),
                            onPressed: () => zet(() {
                              vertraging = (vertraging - 10).clamp(-1000, 1000);
                              schuifNu(keuze);
                            }),
                          ),
                          Expanded(
                            child: Slider(
                              key: const ValueKey('zone-samen-schuif'),
                              value: vertraging.clamp(-1000, 1000).toDouble(),
                              min: -1000,
                              max: 1000,
                              divisions: 200,
                              onChanged: (v) => zet(() => vertraging = v.round()),
                              onChangeEnd: (_) => schuifNu(keuze),
                            ),
                          ),
                          IconButton(
                            key: const ValueKey('zone-samen-plus'),
                            tooltip: '10 ms later',
                            icon: const Icon(Icons.add_rounded),
                            onPressed: () => zet(() {
                              vertraging = (vertraging + 10).clamp(-1000, 1000);
                              schuifNu(keuze);
                            }),
                          ),
                        ]),
                      ],
                      Align(
                        alignment: Alignment.centerRight,
                        child: GlasKnop(
                          key: const ValueKey('zone-groep-klaar'),
                          icoon: Icons.check_rounded,
                          label: 'Klaar',
                          onPressed: () => Navigator.of(ctx).pop(true),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    ),
  );
  if (ok != true || !context.mounted) return;
  if (setEquals(keuze, inGroep)) return;
  final leden = [for (final id in ids) if (keuze.contains(id)) id];
  final fout = await lijst.stuur
      ?.call(leider.id, {'cmd': 'groepeer', 'leden': leden, if (gemengd(keuze)) 'vertragingMs': vertraging});
  if (!context.mounted) return;
  // Wie nu leidt: een toestel met een Sonos geeft de leiding aan die Sonos (zie de server). Keek je naar een
  // zone die nu volgt (het toestel zelf, of dit toestel), dan kijk je voortaan naar de leider.
  final nieuweLeider = speaker ? leider.id : leden.where((id) => id.startsWith('spk:')).firstOrNull ?? leider.id;
  if (fout == null &&
      gekozen != null &&
      nieuweLeider != gekozen.gekozen &&
      (gekozen.gekozen == leider.id || leden.contains(gekozen.gekozen))) {
    gekozen.kies(nieuweLeider);
  }
  _srcToast(
      context,
      fout ??
          (keuze.isEmpty
              ? '$eigenNaam speelt weer alleen.'
              : 'Spelen nu samen: ${[eigenNaam, for (final id in leden) naamVan(id)].join(' + ')}.'));
}

/// "Verplaats naar …" (Saber, 21-10-2026: "overdragen naar elke zone"): kies waar de muziek van [van]
/// verder speelt. Keek je naar [van], dan kijk je daarna naar de nieuwe zone: je volgt de muziek.
Future<void> _kiesDoelZone(BuildContext context, ZoneStaat van) async {
  final lijst = context.read<ZoneLijst>();
  final gekozen = _misschien<GekozenZone>(context);
  final doelen = [for (final z in lijst.zones) if (z.id != van.id && z.online) z];
  final doel = await showModalBottomSheet<ZoneStaat>(
    context: context,
    backgroundColor: Colors.transparent,
    builder: (ctx) => SafeArea(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 480),
          child: GlasVlak(
            vorm: const BorderRadius.all(Radius.circular(18)),
            kleur: _panel,
            balk: true,
            bovenop: true,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(14, 14, 14, 10),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Verplaats naar', style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w700)),
                  const SizedBox(height: 2),
                  Text('${van.naam} pauzeert zodra het daar speelt',
                      style: TextStyle(color: _muted, fontSize: 12)),
                  const SizedBox(height: 8),
                  if (doelen.isEmpty)
                    Padding(
                      padding: const EdgeInsets.symmetric(vertical: 12),
                      child: Text('Geen andere zone bereikbaar.', style: TextStyle(color: _muted, fontSize: 13)),
                    ),
                  for (final z in doelen)
                    Pressable(
                      key: ValueKey('zone-doel-${z.id}'),
                      onPressed: () => Navigator.of(ctx).pop(z),
                      borderRadius: BorderRadius.circular(10),
                      scaleOnFocus: false,
                      vastePlek: false,
                      child: Padding(
                        padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 4),
                        child: Row(children: [
                          Icon(zoneIcoon(z.soort), size: 20, color: _muted),
                          const SizedBox(width: 12),
                          Expanded(
                            child: Text(z.id == lijst.hier ? '${z.naam} · dit toestel' : z.naam,
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600)),
                          ),
                          if (z.playing) Text('speelt', style: TextStyle(color: _muted, fontSize: 11.5)),
                        ]),
                      ),
                    ),
                ],
              ),
            ),
          ),
        ),
      ),
    ),
  );
  if (doel == null || !context.mounted) return;
  final fout = await lijst.verplaats?.call(van.id, doel.id);
  if (!context.mounted) return;
  if (fout != null) {
    _srcToast(context, fout);
    return;
  }
  if (gekozen != null && gekozen.gekozen == van.id) gekozen.kies(doel.id);
  _srcToast(context, 'Naar ${doel.naam} verplaatst — ${van.naam} pauzeert zodra het daar speelt.');
  Navigator.of(context).maybePop();
}

/// "Hier verder" vanaf [zone]: haal haar volledige stand (met de wachtrij) en neem over zoals de balk
/// "Hier verder luisteren" dat doet — dat toestel pauzeert.
Future<void> _neemOverVan(BuildContext context, ZoneStaat zone) async {
  final verder = context.read<VerderLuisteren>();
  final haal = context.read<ZoneLijst>().haalStand;
  final nav = Navigator.of(context);
  Map<String, dynamic>? stand;
  try {
    stand = await haal?.call(zone.id);
  } catch (_) {
    stand = null;
  }
  final ok = await verder.neemOverUit(stand);
  if (!context.mounted) return;
  if (ok) {
    nav.maybePop();
  } else {
    _srcToast(context, stand == null ? 'De pc antwoordt niet.' : 'Dat nummer staat niet in je bibliotheek hier.');
  }
}

/// "Speel daar" (vroeger "Speel op …", Saber 17-10-2026): wat de pc speelt, naar het toestel [id], op
/// dezelfde plek in het nummer; de pc pauzeert zodra het daar speelt. Alleen op de pc.
void _speelOpToestel(BuildContext context, String id, String naam) {
  final sharing = context.read<LanSharing>();
  final p = context.read<PlayerStore>();
  final t = p.current;
  if (t == null) return;
  final rij = p.queueTracks;
  final radio = context.read<RadioBesturing>();
  final ok = sharing.stuurNaar(id, t.path, p.position, [for (final x in rij) x.path], p.currentIndex,
      shuffle: p.shuffle,
      herhaal: p.repeat.name,
      radio: p.radioMode ? {'artiest': radio.zaadArtiest ?? '', 'naam': radio.naam} : null);
  _srcToast(context,
      ok ? 'Naar $naam gestuurd — de pc pauzeert zodra het daar speelt.' : 'Dit nummer kan niet mee (het staat niet in je bibliotheek).');
}

/// Het hart naast de titel in de spelerbalk: vol als dit nummer een favoriet is, en het klopt met
/// deeltjes als het er een wordt (Saber, 17-10-2026). Een tik zet het aan of uit.
class _HartKnop extends StatelessWidget {
  const _HartKnop({required this.track});

  final Track track;

  @override
  Widget build(BuildContext context) {
    final fav = context.watch<Favorieten>();
    final aan = fav.isFavorietTrack(track);
    return Padding(
      padding: const EdgeInsets.only(left: 4),
      child: IconButton(
        tooltip: aan ? 'Uit favorieten' : 'Favoriet',
        visualDensity: VisualDensity.compact,
        padding: EdgeInsets.zero,
        constraints: const BoxConstraints.tightFor(width: 28, height: 28),
        icon: HartIcoon(aan: aan, maat: 17, kleurUit: _muted),
        onPressed: () => fav.wisselTrack(track),
      ),
    );
  }
}

/// Kies een afspeellijst om [nummers] in te zetten — of maak er ter plekke een.
///
/// Eén dialoog voor beide, want "welke lijst" en "een nieuwe" zijn dezelfde vraag: bij de eerste
/// keer is er nog niets om uit te kiezen, en een apart scherm om eerst een lege lijst te maken zou
/// dat moment onnodig in tweeën knippen.
Future<void> _kiesAfspeellijst(BuildContext context, List<String> nummers) async {
  if (nummers.isEmpty) return;
  final lijsten = context.read<Afspeellijsten>();
  final gekozen = await showDialog<String>(
    context: context,
    builder: (ctx) => AlertDialog(
      backgroundColor: _panel,
      title: Text(
          nummers.length == 1 ? 'In welke afspeellijst?' : '${nummers.length} nummers — waarin?',
          style: const TextStyle(fontSize: 17, fontWeight: FontWeight.w700)),
      contentPadding: const EdgeInsets.fromLTRB(0, 12, 0, 0),
      content: SizedBox(
        width: dialogWidth(context, 420),
        child: ListView(
          shrinkWrap: true,
          children: [
            ListTile(
              autofocus: true,
              leading: Icon(Icons.add_rounded, color: _accent),
              title: Text('Nieuwe afspeellijst…', style: TextStyle(color: _accent)),
              onTap: () => Navigator.pop(ctx, ''),
            ),
            if (lijsten.leeg)
              Padding(
                padding: EdgeInsets.fromLTRB(24, 8, 24, 16),
                child: Text('Je hebt er nog geen.',
                    style: TextStyle(color: _muted, fontSize: 12.5)),
              ),
            for (final p in lijsten.lijsten)
              ListTile(
                leading: Icon(Icons.queue_music_rounded, color: _muted),
                title: Text(p.name),
                subtitle: Text('${p.trackIds.length} nummers',
                    style: TextStyle(color: _muted, fontSize: 11.5)),
                onTap: () => Navigator.pop(ctx, p.id),
              ),
          ],
        ),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Annuleren')),
      ],
    ),
  );
  if (gekozen == null || !context.mounted) return;

  if (gekozen.isEmpty) {
    final naam = await _vraagNaam(context, 'Nieuwe afspeellijst', '');
    if (naam == null || naam.trim().isEmpty) return;
    await lijsten.maak(naam.trim(), nummers: nummers);
    if (context.mounted) _srcToast(context, '“${naam.trim()}” aangemaakt met ${nummers.length} ${nummers.length == 1 ? 'nummer' : 'nummers'}.');
    return;
  }
  await lijsten.voegToe(gekozen, nummers);
  if (context.mounted) {
    _srcToast(context, '${nummers.length} ${nummers.length == 1 ? 'nummer' : 'nummers'} toegevoegd aan “${lijsten.byId(gekozen)?.name ?? ""}”.');
  }
}

Future<String?> _vraagNaam(BuildContext context, String titel, String begin) {
  final c = TextEditingController(text: begin);
  return showDialog<String>(
    context: context,
    builder: (ctx) => AlertDialog(
      backgroundColor: _panel,
      title: Text(titel, style: const TextStyle(fontSize: 17, fontWeight: FontWeight.w700)),
      content: TextField(
        controller: c,
        autofocus: !isTv,
        decoration: const InputDecoration(hintText: 'Naam'),
        onSubmitted: (v) => Navigator.pop(ctx, v),
      ),
      actions: [
        TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Annuleren')),
        FilledButton(
            style: FilledButton.styleFrom(backgroundColor: _knopVulling),
            onPressed: () => Navigator.pop(ctx, c.text),
            child: const Text('Bewaren')),
      ],
    ),
  );
}

