/// Van een zin naar een opdracht.
///
/// Op een gekoppeld toestel gaat de vraag naar de pc, precies zoals zoeken en downloaden dat al doen:
/// dan staat de AI-sleutel op één plek en hoeft je telefoon hem niet te kennen. Zelfde afspraak als
/// voor de TorBox-sleutel.
Future<RadioOpdracht> _vraagRadioplan(BuildContext context, String zin) async {
  final client = context.read<LibraryStore>().remote;
  if (client != null) {
    return leesRadioOpdracht(await client.ask('/api/radio', {'op': 'plan', 'zin': zin}));
  }
  final cfg = context.read<AppSettings>();
  return AiService(() => cfg.anthropicKey, werkruimteVan: () => cfg.anthropicWorkspace)
      .maakRadioplan(zin);
}

/// Van zaadartiesten naar echte nummers.
///
/// **Hier komt de lijst vandaan, en niet uit het taalmodel.** Vijfhonderd tracktitels uit het hoofd
/// van een model zijn voor een deel verzonnen; Deezer weet wat er bestaat. De artiesten zíjn het
/// tijdvak: de toppers van 2 Unlimited en Culture Beat zijn jaren negentig, en er is geen jaartal
/// nodig om dat af te dwingen.
///
/// **En de bekendste nummers onder het genre** ([lastfmSleutel], zie [genreNummersErbij]): de tag op Last.fm
/// ("eurodance", "nederpop") geeft klassiekers van artiesten die het model niet noemde — hoogstens een derde.
Future<List<RecTrack>> _nummersVoor(RadioOpdracht o, {String lastfmSleutel = ''}) async {
  if (o.zaadArtiesten.isEmpty) return const [];
  final rec = RecommendService();
  // Ruimer ophalen dan er gevraagd is, want `kiesNummers` haalt er straks de dubbele uitvoeringen en
  // de overtollige remixen weer uit — en bij dance uit de jaren negentig is dat een flink deel. Wie
  // hier precies het gevraagde aantal ophaalt, houdt na het zeven twee derde over.
  final ruim = o.aantal + (o.aantal >> 1);
  final perArtiest = (ruim / o.zaadArtiesten.length).ceil().clamp(4, 25).toInt();
  final uit = <RecTrack>[];
  final gezien = <String>{};
  // Vier tegelijk. Deezer is keyless en veertig verzoeken in één klap is precies hoe je daar tegen
  // een grens loopt; vier per keer duurt een paar seconden en komt gewoon aan.
  for (var i = 0; i < o.zaadArtiesten.length && uit.length < ruim; i += 4) {
    final blok = o.zaadArtiesten.skip(i).take(4);
    final lijsten = await Future.wait(
        [for (final a in blok) rec.topVan(a, limit: perArtiest).catchError((_) => <RecTrack>[])]);
    for (final l in lijsten) {
      for (final t in l) {
        // Op de VOLLEDIGE titel, niet op `recNorm`. Die gooit alles tussen haakjes weg, dus "Mr.
        // Vain (Radio Edit)" en "Mr. Vain (Club Mix)" zijn daar één sleutel — en dan overleeft
        // gewoon degene die Deezer toevallig eerst noemde. Hier moeten allebei nog door, want
        // `kiesNummers` hieronder is wat er verstandig tussen kiest.
        if (gezien.add('${recNorm(t.artist)}|${t.title.trim().toLowerCase()}')) uit.add(t);
      }
    }
  }
  if (lastfmSleutel.trim().isNotEmpty && o.genre.trim().isNotEmpty) {
    try {
      final tag = await _lastfmBron.tagNummers(o.genre, sleutel: lastfmSleutel, limit: 60);
      final namen = genreNummersErbij(tag ?? const [], max: ruim ~/ 3);
      if (namen.isNotEmpty) {
        final gevonden = await rec.lijstOpDeezer([for (final n in namen) AiNummer(n.artiest, n.titel)],
            elders: _itunesVoorModel, eldersNaam: 'iTunes', van: 'de tag "${o.genre}"');
        for (final t in gevonden) {
          if (gezien.add('${recNorm(t.artist)}|${t.title.trim().toLowerCase()}')) uit.add(t);
        }
      }
    } catch (_) {/* zonder de tag: de artiesten van de zin, zoals voorheen */}
  }
  // Door elkaar, anders speelt hij eerst alles van de eerste artiest. Dat is geen radio maar een
  // discografie.
  uit.shuffle();
  // Zeven vóór het aftellen. `_radioplan` doet het straks nog een keer — dat is de weg waar élke
  // radio langskomt — maar als het pas dáár gebeurt is er niets meer om het gat mee te vullen en
  // levert een radio van driehonderd er tweehonderd op.
  final gekozen = kiesNummers([for (final t in uit) (artiest: t.artist, titel: t.title)]);
  return [for (final i in gekozen.take(o.aantal)) uit[i]];
}

/// Het blad waarin je je zin typt.
Future<void> toonRadioUitZin(BuildContext context) async {
  final ctl = TextEditingController();
  await showModalBottomSheet<void>(
    context: context,
    // Over de glazen balken heen, niet eronder: die liggen sinds 16-10-2026 óver de pagina's.
    useRootNavigator: true,
    backgroundColor: _panel,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(kHoek18))),
    builder: (blad) => Padding(
      // Boven het toetsenbord uit, anders typ je blind.
      padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(blad).bottom),
      child: _RadioUitZinBlad(ctl: ctl),
    ),
  );
  ctl.dispose();
}

class _RadioUitZinBlad extends StatefulWidget {
  const _RadioUitZinBlad({required this.ctl});
  final TextEditingController ctl;

  @override
  State<_RadioUitZinBlad> createState() => _RadioUitZinBladState();
}

class _RadioUitZinBladState extends State<_RadioUitZinBlad> {
  bool _bezig = false;
  String? _fout;
  RadioOpdracht? _begrepen;

  Future<void> _denk() async {
    setState(() {
      _bezig = true;
      _fout = null;
    });
    try {
      final o = await _vraagRadioplan(context, widget.ctl.text);
      if (!mounted) return;
      setState(() {
        _bezig = false;
        // Zonder artiesten valt er niets op te zoeken, en dan is "ik snapte het niet" het eerlijke
        // antwoord in plaats van een radio die stil leeg blijft.
        if (o.bruikbaar) {
          _begrepen = o;
        } else {
          _fout = 'Ik heb er geen artiesten uit kunnen halen. Probeer het wat concreter — '
              'bijvoorbeeld "eurodance uit de jaren 90, 200 nummers".';
        }
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _fout = e is AiFout ? e.uitleg : '$e';
        _bezig = false;
      });
    }
  }

  Future<void> _start() async {
    final o = _begrepen;
    if (o == null) return;
    setState(() => _bezig = true);
    final nummers = await _nummersVoor(o, lastfmSleutel: context.read<AppSettings>().lastfmKey);
    if (!mounted) return;
    if (nummers.isEmpty) {
      setState(() {
        _bezig = false;
        _fout = 'Bij die artiesten kwam geen enkel nummer boven. Probeer het anders te zeggen.';
      });
      return;
    }
    final lib = context.read<LibraryStore>();
    final radio = context.read<RadioBesturing>();
    final cfg = context.read<AppSettings>();
    final rec = RecommendService();
    final log = WarmLog('$appDir${Platform.pathSeparator}radio.log');
    final genoemd = {for (final a in o.zaadArtiesten) artiestSleutel(a)};
    // Dezelfde keuring als een radio vanaf een nummer (Saber, 22-10-2026: "Werkt dit voor alle radio functies in
    // de app?"): het genre van de zin als familie en danstak, het sfeeroordeel van het model, en de jaren die je
    // zelf noemde. Zonder zaadnummer: geen tempo, en het "zaad" van de sfeervraag is de naam van de radio.
    final remote = lib.isRemote ? lib.remote : null;
    final viaPc = remote != null && context.read<ClientSession>().pcHeeftModel;
    final familie = familieVan(o.genre);
    final ai = _radioModel(cfg: cfg, lib: lib, remote: remote, viaPc: viaPc, radio: radio, log: log);
    final keuring = _Radiokeuring(
      artiest: o.naam,
      zaad: null,
      zaadTitel: null,
      stijlboek: _gedeeldStijlboek(cfg),
      zaadStijl: Future.value((familie: familie, jaar: null)),
      log: log,
    )
      ..model = ai
      ..budget = viaPc ? null : _modelbudget
      ..jaarVan = o.jaarVan
      ..jaarTot = o.jaarTot
      ..danstakVanZin = familie == Stijlfamilie.dans ? danstakkenVan([o.genre]).firstOrNull : null;
    // Een zin-radio vraagt het model geen lijst: de keuring hoeft er niet op te wachten.
    keuring.lijstKlaar();
    log.line('radio uit een zin "${o.naam}": genre ${familie?.name ?? '?'}'
        '${keuring.danstakVanZin == null ? '' : ', ${keuring.danstakVanZin}'}'
        '${o.jaarVan == null && o.jaarTot == null ? '' : ', jaren ${o.jaarVan ?? '…'}–${o.jaarTot ?? '…'}'}'
        '${ai == null ? ', zonder model' : ''}');
    final beurt = ++_afstemBeurt;
    // Bijvullen uit de toppers van de genoemde artiesten zelf — die zíjn het genre — en gekeurd.
    final lastfmSleutelZin = context.read<AppSettings>().lastfmKey.trim();
    final bijvuller = Radiobijvuller(
      radio: radio,
      deezer: Radiodeezer(
        bronArtiesten: (a, verwant) => rec.bronArtiesten(a, metVerwant: verwant),
        toppers: (id, naam, limit, index) => rec.toppers(id, naam, limit: limit, index: index),
      ),
      ankers: o.zaadArtiesten,
      metVerwant: false,
      maakPlan: (recs) => _radioplan(recs, lib,
          al: artiestenVoorPlafond(radio.plan, voorbijteller: radio.voorbijteller), bron: 'buren'),
      reserveKandidaten: (artiesten) => [
        for (final t in lib.tracks)
          if (!nooitOpRadio(t.title) && artiesten.contains(artiestSleutel(t.artist))) t
      ],
      keurEigen: (p) => keuring.keur(p, eigen: true),
      vraagSfeer: ai == null ? null : (plekken) => keuring.vraagSfeer(plekken, onderweg: true),
      // Ontdekken onderweg: wat Last.fm vergelijkbaar vindt met wat net speelde (zie [kLastfmPerRonde]).
      lastfmVan: lastfmSleutelZin.isEmpty
          ? null
          : (a, t) => _lastfmPlekken(a, t,
              sleutel: lastfmSleutelZin,
              lib: lib,
              rec: rec,
              spoor: log.line,
              maakPlan: (recs) => _radioplan(recs, lib,
                  al: artiestenVoorPlafond(radio.plan, voorbijteller: radio.voorbijteller), bron: 'lastfm')),
      spoor: log.line,
    );
    log.line('radio uit een zin "${o.naam}": ${o.zaadArtiesten.length} artiesten, '
        '${o.aantalGenoemd ? 'stopt bij ${o.aantal}' : 'geen aantal genoemd, vult door'}');
    final plan = _radioplan(nummers, lib);
    keuring.vraagSfeer(plan);
    // Eigen nummers pas na de keuring, zoals bij [startRadio]; wat gehaald moet worden keurt de haal zelf.
    final halen = [for (final p in plan) if (p.eigen == null) p];
    int? gestart;
    final reden = await radio.start(halen.isEmpty ? plan : halen,
        naam: o.naam,
        keur: keuring.keur,
        bijvul: bijvuller.call,
        spoor: log.line,
        aantal: o.aantalGenoemd ? o.aantal : null,
        // Het vangnet pas als deze start het werd.
        bijStart: (s) {
          gestart = s;
          radio.eigenVanZaad = () => [
                for (final t in lib.tracks)
                  if (!nooitOpRadio(t.title) && genoemd.contains(artiestSleutel(t.artist))) t
              ];
        });
    final sessie = gestart;
    if (reden == null && sessie != null && halen.isNotEmpty) {
      _voegGekeurdBij(radio, sessie, beurt, keuring, [for (final p in plan) if (p.eigen != null) p]);
    }
    if (!mounted) return;
    if (reden != null) {
      setState(() {
        _bezig = false;
        _fout = reden;
      });
      return;
    }
    Navigator.pop(context);
  }

  @override
  Widget build(BuildContext context) {
    final o = _begrepen;
    return SafeArea(
      top: false,
      child: Padding(
        padding: const EdgeInsets.all(kRuimte24),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Text('NIEUWE RADIO',
                style: TextStyle(
                    fontSize: 11, fontWeight: FontWeight.w600, letterSpacing: .6, color: kAccent2)),
            const SizedBox(height: kRuimte8),
            const Text('Zeg wat je wil horen',
                style: TextStyle(fontSize: 25, fontWeight: FontWeight.w700, letterSpacing: -.4)),
            const SizedBox(height: kRuimte6),
            Text('Gewoon een zin. De rest zoekt hij zelf uit.',
                style: TextStyle(fontSize: 13.5, color: _muted)),
            const SizedBox(height: kRuimte16),
            TextField(
              controller: widget.ctl,
              autofocus: true,
              maxLines: 3,
              minLines: 2,
              textInputAction: TextInputAction.done,
              onSubmitted: (_) => _bezig ? null : _denk(),
              decoration: InputDecoration(
                hintText: 'maak me een radio met 300 liedjes van de jaren 90, genre eurodance',
                filled: true,
                fillColor: kVerzonken,
                border: OutlineInputBorder(borderSide: BorderSide.none),
              ),
            ),
            if (_fout != null) ...[
              const SizedBox(height: kRuimte12),
              Text(_fout!, style: TextStyle(fontSize: 12.5, color: leesbaar(const Color(0xFFE8913A)))),
            ],
            if (o != null) ...[
              const SizedBox(height: kRuimte16),
              _begrip(o),
            ],
            const SizedBox(height: kRuimte16),
            FilledButton(
              onPressed: _bezig ? null : (o == null ? _denk : _start),
              child: _bezig
                  ? const SizedBox(
                      width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2))
                  : Text(o == null ? 'Begrijp mijn zin' : 'Radio starten'),
            ),
          ],
        ),
      ),
    );
  }

  /// Wat het model ervan gemaakt heeft — vóórdat er iets gedownload wordt.
  ///
  /// **Waarom dit getoond wordt en er niet meteen gestart wordt.** Vijfhonderd nummers is zo'n
  /// drieëndertig uur muziek en enkele gigabytes op je pc. Dat hoort niet te beginnen omdat een model
  /// jouw "vijftig" als "vijfhonderd" las. Boven de honderd staat het er met uren en gigabytes bij, in
  /// gewone taal.
  Widget _begrip(RadioOpdracht o) {
    // Ruw, en dat is genoeg: vier minuten per nummer, en een FLAC van vier minuten is een kleine
    // veertig megabyte. Het gaat om de orde van grootte, niet om het cijfer achter de komma.
    final uren = (o.aantal * 4 / 60).round();
    final gb = (o.aantal * 38 / 1024).toStringAsFixed(1);
    return Container(
      padding: const EdgeInsets.all(kRuimte12),
      decoration: BoxDecoration(
        color: kVerzonken,
        borderRadius: BorderRadius.circular(kHoek12),
        border: Border.all(color: kLijnZacht),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(o.naam, style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700)),
          const SizedBox(height: kRuimte4),
          Text('${o.aantal} nummers · begint bij ${o.zaadArtiesten.length} artiesten',
              style: TextStyle(fontSize: 12, color: _muted)),
          const SizedBox(height: kRuimte8),
          Wrap(
            spacing: kRuimte6,
            runSpacing: kRuimte6,
            children: [
              for (final a in o.zaadArtiesten.take(7))
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                  decoration: BoxDecoration(
                      color: _panel2,
                      borderRadius: BorderRadius.circular(kHoekRond),
                      border: Border.all(color: kLijn)),
                  child: Text(a, style: const TextStyle(fontSize: 11)),
                ),
              if (o.zaadArtiesten.length > 7)
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 4),
                  child: Text('+${o.zaadArtiesten.length - 7} meer',
                      style: TextStyle(fontSize: 11, color: _muted)),
                ),
            ],
          ),
          if (o.aantal > kVraagBovenaantal) ...[
            const SizedBox(height: kRuimte12),
            Text(
                '${o.aantal} nummers is ongeveer $uren uur muziek en zo’n $gb GB op je pc. Hij '
                'haalt ze pas op terwijl je luistert, en wat je niet groen geeft ruimt hij achteraf '
                'weer op.',
                style: TextStyle(fontSize: 11.5, color: _muted, height: 1.45)),
          ],
        ],
      ),
    );
  }
}

// ── Het overzicht bij het afsluiten van een radio ────────────────────────────

/// Wat er van deze radio blijft en wat er weggaat, met een kans om je te bedenken.
///
/// **Waarom dit scherm er is en niet meteen gewist wordt.** Een duim omlaag betekent "van mijn schijf
/// af", en wissen heeft geen weg terug. Dat meteen bij de tik doen zou betekenen dat één misgetikte
/// knop een bestand kost. Dus: opschrijven tijdens het luisteren, en één keer aan het eind laten zien
/// wat het bij elkaar wordt — met "Toch houden" naast elke regel.
///
/// Ook wat je NIET beoordeeld hebt staat hier bij "gaat weg". Dat is met zoveel woorden gekozen, en
/// het hoort zichtbaar te zijn in plaats van in een instelling te staan: de radio is een manier om
/// muziek te proberen, en wat je niet hebt aangewezen heb je niet gekozen.
Future<void> toonRadioOverzicht(BuildContext context, RadioSessie sessie) async {
  final radio = context.read<RadioBesturing>();
  final lib = context.read<LibraryStore>();
  final oordelen = context.read<Oordelen>();
  final fav = context.read<Favorieten>();
  final lijsten = context.read<Afspeellijsten>();
  final downloads = context.read<DownloadManager>();
  final gered = <String>{};

  Track? nummerVan(Gehaald g) => lib.ownedTrack(g.artiest, g.titel);

  // Welk bestand hoort bij deze regel? Zie [bestandVanGehaald]: nooit zomaar iets met dezelfde
  // artiest en titel, want dat kan je eigen exemplaar zijn. Null: weg.
  String? padVan(Gehaald g) {
    final t = nummerVan(g);
    return bestandVanGehaald(g,
        eigenPad: t?.path,
        eigenId: t == null ? null : lib.gedeeldId(t.path),
        opAfstand: lib.isRemote,
        bestaat: (p) => File(p).existsSync());
  }

  // Alleen wat er nog IS: een regel voor een bestand dat al weg is valt niets meer aan te beslissen,
  // en telde wel mee in "Afsluiten en 19 opruimen".
  final aanwezig = [
    for (final g in sessie.gehaald)
      if (padVan(g) != null) g
  ];
  if (aanwezig.isEmpty) {
    // Maar niet als de muziekschijf er gewoon niet is: dan is alles "weg" omdat de schijf los is, en
    // zou de notitie verdwijnen met de bestanden er nog op.
    if (!lib.isRemote &&
        sessie.gehaald.any((g) => g.pad.length >= 3 && !Directory(g.pad.substring(0, 3)).existsSync())) {
      return;
    }
    await radio.vergeetOpenstaand();
    return;
  }

  // Het nummer op het pad van [padVan] — het bestand van de radio zelf. De bescherming (duim omhoog,
  // favoriet, afspeellijst) hoort op DAT bestand te kijken en niet op het eerste met dezelfde naam:
  // anders zag een favoriete radiosingle er onbeschermd uit omdat je album-versie geen hart had.
  final opPad = {for (final t in lib.tracks) t.path: t};
  Track? nummerOp(Gehaald g) {
    final p = padVan(g);
    return p == null ? null : opPad[p];
  }

  // In een afspeellijst? Dan blijft hij, wat er verder ook op staat. Een afspeellijst met een gat
  // erin is stuk, en dat merk je pas maanden later.
  final inLijst = <String>{for (final l in lijsten.lijsten) ...l.trackIds};

  Opruimplan maakPlan() => opruimplan(
        gehaald: aanwezig,
        oordeel: (g) {
          final t = nummerOp(g);
          return t != null ? oordelen.vanTrack(t) : oordelen.van(g.id);
        },
        isFavoriet: (g) {
          final t = nummerOp(g);
          return t != null && fav.isFavorietTrack(t);
        },
        inAfspeellijst: (g) {
          final t = nummerOp(g);
          final id = (t != null ? lib.gedeeldId(t.path) : null) ?? g.id;
          return id != null && inLijst.contains(id);
        },
        gered: gered,
      );

  final doen = await showModalBottomSheet<bool>(
    context: context,
    backgroundColor: _panel,
    isScrollControlled: true,
    shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(kHoek18))),
    builder: (blad) => StatefulBuilder(
      builder: (blad, herteken) {
        final plan = maakPlan();
        return SafeArea(
          top: false,
          child: ConstrainedBox(
            constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(blad).height * .85),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(kRuimte24, kRuimte24, kRuimte24, 0),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text('Radio afsluiten'.toUpperCase(),
                          style: TextStyle(
                              fontSize: 11,
                              fontWeight: FontWeight.w600,
                              letterSpacing: .6,
                              color: _accent)),
                      const SizedBox(height: kRuimte8),
                      Text(sessie.naam.isEmpty ? 'Je radio' : sessie.naam,
                          style: const TextStyle(
                              fontSize: 25, fontWeight: FontWeight.w700, letterSpacing: -.4)),
                      const SizedBox(height: kRuimte6),
                      Text(
                          'Deze radio haalde ${aanwezig.length} '
                          '${aanwezig.length == 1 ? "nummer" : "nummers"} voor je op.',
                          style: TextStyle(fontSize: 13.5, color: _muted, height: 1.4)),
                    ],
                  ),
                ),
                Flexible(
                  child: ListView(
                    shrinkWrap: true,
                    padding: const EdgeInsets.fromLTRB(kRuimte24, kRuimte16, kRuimte24, 0),
                    children: [
                      if (plan.blijft.isNotEmpty) ...[
                        _overzichtKop('Deze blijven', kHouden, plan.blijft.length),
                        for (final g in plan.blijft) _overzichtRegel(g, null),
                      ],
                      if (plan.weg.isNotEmpty) ...[
                        if (plan.blijft.isNotEmpty) const SizedBox(height: kRuimte16),
                        _overzichtKop('Deze gaan weg', kWeg, plan.weg.length),
                        for (final g in plan.weg)
                          _overzichtRegel(g, () => herteken(() => gered.add(g.pad))),
                      ],
                    ],
                  ),
                ),
                Padding(
                  padding: const EdgeInsets.fromLTRB(kRuimte24, kRuimte16, kRuimte24, kRuimte16),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Text(
                          heeftPrullenbak || lib.isRemote
                              ? 'Opruimen zet ze in de prullenbak: daar haal je ze terug zolang je '
                                  'die niet leegt. Wat je zelf al had blijft hoe dan ook staan — die '
                                  'raakt de radio niet aan.'
                              : 'Weggaan is van dit toestel af, niet alleen uit deze lijst. Wat je '
                                  'zelf al had blijft hoe dan ook staan — die raakt de radio niet aan.',
                          style: TextStyle(fontSize: 11.5, color: _muted, height: 1.45)),
                      const SizedBox(height: kRuimte12),
                      // NAAST elkaar en niet onder elkaar. Op 26-09-2026 stonden ze twintig punten
                      // boven elkaar, en een klik die voor "Later beslissen" bedoeld was werd
                      // "Afsluiten en 19 opruimen". Naast elkaar kan een klik die een paar punten te
                      // hoog of te laag valt nooit de andere knop worden. En "Later" links: de kant
                      // waar je begint te lezen is de kant die niets kapotmaakt.
                      Row(
                        children: [
                          Expanded(
                            child: OutlinedButton(
                              onPressed: () => Navigator.pop(blad, false),
                              child: const Text('Later beslissen'),
                            ),
                          ),
                          const SizedBox(width: kRuimte16),
                          Expanded(
                            child: FilledButton(
                              onPressed: () => Navigator.pop(blad, true),
                              child: Text(
                                  plan.weg.isEmpty
                                      ? 'Afsluiten'
                                      : '${plan.weg.length} naar de prullenbak',
                                  textAlign: TextAlign.center),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ],
            ),
          ),
        );
      },
    ),
  );

  // "Later beslissen" laat de notitie staan: dan komt hetzelfde overzicht bij de volgende start
  // gewoon terug. Dat is beter dan hem stil laten verdwijnen met de bestanden er nog.
  if (doen != true) return;

  final plan = maakPlan();
  final paden = <String>[];
  final padVanRegel = <Gehaald, String>{};
  for (final g in plan.weg) {
    final pad = padVan(g);
    if (pad == null) continue; // intussen al weg
    paden.add(pad);
    padVanRegel[g] = pad;
    // Van de verlanglijst af. Zonder dit haalt `sweepLosslessWants` twintig minuten later alsnog de
    // FLAC van een nummer dat je zojuist hebt weggedaan — en dat is niet alleen vervelend maar
    // onbegrijpelijk: je gooide het weg en het staat er weer.
    unawaited(downloads.vergeetWens(g.artiest, g.titel).catchError((_) {}));
  }
  if (paden.isEmpty) {
    await radio.vergeetOpenstaand();
    return;
  }
  final weg = await lib.removeTracks(paden, fromDisk: true, naarPrullenbak: true);
  // Alleen vergeten wat beslist IS: wat blijft, en wat werkelijk van zijn plek is. Wat niet naar de
  // prullenbak kon — een schijf zonder prullenbak, een bestand dat openstond — staat er nog, en komt
  // de volgende keer terug in dit overzicht in plaats van voorgoed uit beeld te raken.
  // Op een gekoppeld toestel: de catalogus is na het verzoek opnieuw geladen, dus wat er nog in staat
  // kon de pc niet weg (een netwerkschijf, een bestand dat openstond, een oudere pc).
  final nuInCatalogus = {for (final t in lib.tracks) t.path};
  final nogEr = {
    for (final p in paden)
      if (lib.isRemote ? nuInCatalogus.contains(p) : File(p).existsSync()) p
  };
  await radio.houdAlleen(sessie, (g) {
    final p = padVanRegel[g];
    return p != null && nogEr.contains(p);
  });
  if (!context.mounted) return;
  // En zeggen wat er NIET kon, en waarom. Zonder dat kwam het overzicht na elke radio terug met
  // dezelfde nummers, zonder uitleg (eindbeoordeling van 26-09-2026). Wie ze wil houden, zet ze de
  // volgende keer bij "Houden".
  final bleef = nogEr.length;
  final gedaan = heeftPrullenbak || lib.isRemote
      ? '$weg ${weg == 1 ? "nummer" : "nummers"} naar de prullenbak.'
      : '$weg ${weg == 1 ? "nummer" : "nummers"} opgeruimd.';
  ScaffoldMessenger.of(context).showSnackBar(SnackBar(
    content: Text(bleef == 0
        ? gedaan
        : '$gedaan $bleef ${bleef == 1 ? "kon" : "konden"} niet — een schijf zonder prullenbak of '
            'een bestand dat openstond. Ze staan er nog, en komen de volgende keer terug in dit '
            'overzicht.'),
    duration: Duration(seconds: bleef == 0 ? 4 : 10),
  ));
}

Widget _overzichtKop(String tekst, Color kleur, int aantal) => Padding(
      padding: const EdgeInsets.only(bottom: kRuimte8),
      child: Row(
        children: [
          Container(
              width: 7,
              height: 7,
              decoration: BoxDecoration(color: kleur, shape: BoxShape.circle)),
          const SizedBox(width: kRuimte8),
          Text(tekst.toUpperCase(),
              style: TextStyle(
                  fontSize: 11, fontWeight: FontWeight.w600, letterSpacing: .6, color: kUitgezet)),
          const Spacer(),
          Text('$aantal', style: TextStyle(fontSize: 12, color: _muted)),
        ],
      ),
    );

Widget _overzichtRegel(Gehaald g, VoidCallback? redden) => Padding(
      padding: const EdgeInsets.only(bottom: kRuimte8),
      child: Row(
        children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(g.titel,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(fontSize: 12.5, fontWeight: FontWeight.w600)),
                Text(g.artiest,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(fontSize: 11, color: _muted)),
              ],
            ),
          ),
          if (redden != null)
            TextButton(
              onPressed: redden,
              style: TextButton.styleFrom(
                  foregroundColor: kHouden,
                  padding: const EdgeInsets.symmetric(horizontal: kRuimte12),
                  minimumSize: const Size(0, 32)),
              child: const Text('Toch houden', style: TextStyle(fontSize: 11.5)),
            ),
        ],
      ),
    );

/// Duim omlaag: dit nummer NU weg.
///
/// **Waarom hier geen oordeel meer opgeschreven wordt.** Rood was eerst een notitie: hij werd bewaard
/// en pas bij "Radio afsluiten" uitgevoerd, met een overzicht en een kans om iets terug te halen. Op
/// het toestel bleek dat precies het omgekeerde van de bedoeling — *"vanaf ik de duim omlaag doe, moet
/// het direct verwijderd worden!"*. Een knop met een prullenbakbetekenis die niets zichtbaars doet,
/// druk je nog een keer in, en dan sta je te twijfelen of hij het wel deed.
///
/// Een groen oordeel van eerder gaat wél weg. Zonder dat zou hetzelfde nummer, als het later opnieuw
/// binnenkomt, die duim omhoog erven — van een keuze die je intussen hebt teruggenomen.
/// De knop "Zoek hi-res" op een albumpagina: één zoekopdracht voor het hele album, en voor elk nummer met
/// een duidelijk betere kopie de gewone jacht — zie [DownloadManager.zoekBeterVoor].
Future<void> _zoekHires(BuildContext context, Album album) async {
  final lib = context.read<LibraryStore>();
  _srcToast(context, 'Zoekt een betere kopie voor "${album.title}"…');
  final int n;
  if (lib.remote != null) {
    final r = await zoekBeterOpPc(lib, album.tracks, album: album.title);
    if (!context.mounted) return;
    if (r == null) {
      _srcToast(context, 'Je pc antwoordde niet — probeer het straks opnieuw');
      return;
    }
    if (r < 0) {
      _srcToast(context, 'Je pc zoekt nog een betere kopie voor "${album.title}" — vervangen alleen als het bewezen beter is');
      return;
    }
    n = r;
  } else {
    n = await context.read<DownloadManager>().zoekBeterVoor(album.tracks, album: album.title, gezag: lib.tagsVoorVervanger);
  }
  if (!context.mounted) return;
  _srcToast(
      context,
      n == 0
          ? 'Geen betere kopie gevonden voor "${album.title}" — wat je hebt is het beste dat er nu is'
          : '$n ${n == 1 ? "nummer" : "nummers"} op jacht naar een betere kopie — vervangen alleen als het '
              'bewezen beter is');
}

/// "Zoek hi-res" of 👍 vanaf een toestel: de pc zoekt (`/api/soulseek/zoek-beter`, server.dart). Saber,
/// 21-10-2026: "Kan het dat de functie hi res zoeken, niet op de andere platformen staan?" — ze stond alleen
/// waar het toestel zelf haalt. Geeft terug voor hoeveel nummers de pc een jacht begon, -1 als hij nog
/// zoekt, en null als de pc niet antwoordde.
Future<int?> zoekBeterOpPc(LibraryStore lib, List<Track> nummers, {String? album}) async {
  final c = lib.remote;
  if (c == null) return null;
  final ids = [
    for (final t in nummers)
      if (lib.remoteTrackId(t.path) case final id?) id,
  ];
  if (ids.isEmpty) return 0;
  try {
    final a = await c.ask('/api/soulseek/zoek-beter', {'trackIds': ids, if (album != null) 'album': album});
    return (a['begonnen'] as num?)?.toInt() ?? 0;
  } catch (_) {
    return null;
  }
}

/// 👍 op een nummer dat de radio haalde: houden, en dan ook op jacht naar een betere kopie (Saber,
/// 20-10-2026: "maar bij radio wel bij nummers die ik beslis om bij te houden"). Alleen waar deze machine
/// zelf haalt, en alleen als het nummer nú groen werd — uitzetten zoekt niets.
Future<void> _duimOmhoogRadio(BuildContext context, Track t) async {
  final oordelen = context.read<Oordelen>();
  final lib = context.read<LibraryStore>();
  final dm = lib.remote == null ? context.read<DownloadManager>() : null;
  final nu = await oordelen.wissel(t, Oordeel.omhoog);
  if (nu != Oordeel.omhoog) return;
  // Op een toestel zoekt de pc — zie [zoekBeterOpPc].
  if (dm == null) {
    unawaited(zoekBeterOpPc(lib, [t]));
    return;
  }
  unawaited(dm.zoekBeterVoor([t], gezag: lib.tagsVoorVervanger));
}

Future<void> _duimOmlaag(BuildContext context, Track t) async {
  final radio = context.read<RadioBesturing>();
  final oordelen = context.read<Oordelen>();
  final meldingen = ScaffoldMessenger.of(context);
  final opAfstand = context.read<LibraryStore>().isRemote;
  final naam = '${t.artist} — ${t.title}';
  final id = oordelen.idVanTrack(t);
  if (id != null) unawaited(oordelen.zet(id, null).catchError((_) {}));
  final weg = await radio.gooiWeg(t);
  if (weg == null) return;
  meldingen.showSnackBar(SnackBar(
    content: Text(weg
        ? (heeftPrullenbak || opAfstand
            ? '$naam staat in de prullenbak.'
            : '$naam is weg — ook van je pc.')
        : '$naam kon niet naar de prullenbak en staat er nog. Bij het afsluiten van de radio kun je het opnieuw proberen.'),
    duration: const Duration(seconds: 3),
  ));
}

/// De duimen in de radiorij: dezelfde knop, ter grootte van een regel.
///
/// Tekent zichzelf weg bij een nummer dat de radio niet heeft opgehaald — de beslissing zit hier en
/// niet bij de aanroeper, zodat er maar één plek is waar die regel staat.
class _RijDuimen extends StatelessWidget {
  const _RijDuimen({required this.track, this.alleenHouden = false, this.maat = 28});

  final Track track;

  /// Alleen 👍 ("houden"): in de balk onderaan, waar "weg" naast het hart en de speelknop te makkelijk geraakt
  /// wordt. Het volle paar staat op het speelscherm en in de wachtrij.
  final bool alleenHouden;
  final double maat;

  @override
  Widget build(BuildContext context) {
    final radio = context.watch<RadioBesturing>();
    if (!radio.doorDezeRadio(track.path)) return const SizedBox.shrink();
    final oordelen = context.watch<Oordelen>();
    final nu = oordelen.vanTrack(track);
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        if (!alleenHouden) ...[
          Duim(
            kant: Duimkant.omlaag,
            maat: maat,
            // Nooit ingedrukt: rood wist meteen, dus de regel waar deze duim op staat is er een tel
            // later niet meer. Een stand die je toch niet ziet, is een stand die niet bestaat.
            aan: false,
            gedempt: nu == Oordeel.omhoog,
            opTik: () => unawaited(_duimOmlaag(context, track)),
          ),
          const SizedBox(width: kRuimte4),
        ],
        Duim(
          kant: Duimkant.omhoog,
          maat: maat,
          aan: nu == Oordeel.omhoog,
          gedempt: nu == Oordeel.omlaag,
          opTik: () => unawaited(_duimOmhoogRadio(context, track)),
        ),
        const SizedBox(width: kRuimte4),
      ],
    );
  }
}

/// Gaan de duimen over wat je nu ziet? Op dit toestel altijd; op een gekozen zone alleen als daar de radio van dít
/// toestel speelt — een radio van de pc op een speaker (`speaker_radio.dart`). Een zone met de radio van een ander
/// toestel niet: die radio staat daar.
///
/// **Waarom (Saber, 22-10-2026).** Een radio vanaf Tamino op de KEF: *"wat ik wel nie zie is men duim omhoog of omlaag
/// tijdens het spelen, nu speelt er een fantastisch mooi liedje ik wil direct kunnen zeggen dat ik die wil houden"*.
/// Met de KEF gekozen ("Speelt op: LS50") verborgen alle duimen zich, want de KEF is een zone "op afstand".
bool _radioHier(BuildContext context) {
  final zone = _misschien<GekozenZone>(context, luister: true)?.opAfstand;
  return zone == null || _radioOpGekozenZone(context);
}

/// Speelt de radio van dit toestel op de gekozen zone (en niet op dit toestel zelf)? [luister]: onwaar in een
/// wachtrijregel — de zone tikt elke seconde, en de lijst bouwt zelf al opnieuw als je een andere kiest.
bool _radioOpGekozenZone(BuildContext context, {bool luister = true}) {
  final zone = _misschien<GekozenZone>(context, luister: luister)?.opAfstand;
  if (zone == null) return false;
  final radio = context.watch<RadioBesturing>();
  final uit = radio.speler;
  return radio.loopt && uit is SpeakerRadio && uit.speeltOpZone(zone.zoneId);
}

/// De duimen op het speelscherm ([_RadioOordeel]).
///
/// **Twee paar sinds 21-10-2026.** "Past in deze radio?" bij elk nummer, ook je eigen — een oordeel over de
/// sfeer (zie `radiosfeer.dart`). "Houden of weg?" alleen bij een nummer dat DEZE radio heeft opgehaald: bij
/// muziek die je zelf al had valt er niets weg te gooien, en een rode knop die dat wél suggereert is precies
/// de knop die je een keer per ongeluk raakt. De radio raakt je eigen
/// verzameling niet aan, en dat hoort ook op het scherm te zien te zijn.
///
/// Niet op televisie. Daar is geen aanwijzer, en een oordeel dat je met een afstandsbediening moet
/// aanklikken tussen zeven andere knoppen door is geen oordeel maar een ongeluk in wording. Het
/// overzicht bij het afsluiten is daar het vangnet.
/// De radioregel onder de titel — zie [radioStatusTekst]. Null: niets bijzonders.
String? _radioRegel(BuildContext context, Speelbron p) {
  // Een zone op afstand: haar radio staat op dat toestel, en hier is daar niets van te zeggen.
  if (p is! PlayerStore) return null;
  final r = context.watch<RadioBesturing>();
  return radioStatusTekst(
    spelerStatus: p.radioStatus,
    droog: p.radioDroog,
    wilVerder: p.wilVerder,
    loopt: r.loopt,
    // Kort: in de smalle balk van de telefoon is er plaats voor een kleine dertig tekens.
    stand: r.bijvulStand ?? (r.pauze == null ? null : 'Even stil: ${r.pauze}'),
    aantalBereikt: r.aantalOp,
    aantal: r.aantal,
  );
}

class _RadioOordeel extends StatelessWidget {
  const _RadioOordeel({required this.track, required this.naast});

  final Track? track;
  final bool naast;

  @override
  Widget build(BuildContext context) {
    // Een zone op afstand gekozen: dit gaat over dit toestel, niet over wat je nu ziet (zones, 21-10-2026) — behalve
    // als daar de radio van dit toestel speelt ([_radioHier]).
    if (!_radioHier(context)) return const SizedBox.shrink();
    final t = track;
    final radio = context.watch<RadioBesturing>();
    if (isTv || t == null || !radio.loopt) return const SizedBox.shrink();
    // "Past in deze radio?" bij ELK nummer van de radio, ook je eigen (Saber, 21-10-2026: "net zoals roon
    // doet"); "Houden of weg?" alleen bij wat deze radio haalde — dat gaat over het bestand.
    final gehaald = radio.doorDezeRadio(t.path);
    final sfeer = context.watch<RadioSfeer>();
    final past = sfeer.oordeel(artiest: t.artist, titel: t.title, zaad: radio.sfeerZaad, familie: radio.familie);
    final oordelen = context.watch<Oordelen>();
    final nu = oordelen.vanTrack(t);
    Widget kop(String tekst) => Text(tekst,
        style: TextStyle(fontSize: 11, fontWeight: FontWeight.w600, letterSpacing: .6, color: kUitgezet));
    final uitlijning = naast ? MainAxisAlignment.start : MainAxisAlignment.center;
    return Padding(
      padding: const EdgeInsets.only(top: kRuimte16, bottom: kRuimte8),
      child: Column(
        crossAxisAlignment: naast ? CrossAxisAlignment.start : CrossAxisAlignment.center,
        children: [
          kop('Past in deze radio?'),
          const SizedBox(height: kRuimte8),
          Row(
            mainAxisAlignment: uitlijning,
            children: [
              Duim(
                kant: Duimkant.omlaag,
                aan: past == Sfeeroordeel.pastNiet,
                gedempt: past == Sfeeroordeel.past,
                bijschrift: 'Past niet',
                opTik: () => unawaited(_pastNietInRadio(context, t)),
              ),
              const SizedBox(width: kRuimte24),
              Duim(
                kant: Duimkant.omhoog,
                aan: past == Sfeeroordeel.past,
                gedempt: past == Sfeeroordeel.pastNiet,
                bijschrift: 'Past',
                opTik: () => unawaited(_pastInRadio(context, t)),
              ),
            ],
          ),
          if (gehaald) ...[
            const SizedBox(height: kRuimte16),
            kop('Houden of weg?'),
            const SizedBox(height: kRuimte8),
            Row(
              mainAxisAlignment: uitlijning,
              children: [
                Duim(
                  kant: Duimkant.omlaag,
                  aan: false,
                  gedempt: nu == Oordeel.omhoog,
                  bijschrift: 'Weg, ook van je pc',
                  opTik: () => unawaited(_duimOmlaag(context, t)),
                ),
                const SizedBox(width: kRuimte24),
                Duim(
                  kant: Duimkant.omhoog,
                  aan: nu == Oordeel.omhoog,
                  gedempt: nu == Oordeel.omlaag,
                  bijschrift: 'Houden',
                  opTik: () => unawaited(_duimOmhoogRadio(context, t)),
                ),
              ],
            ),
          ],
        ],
      ),
    );
  }
}

/// "Past niet in deze radio": dit nummer niet meer in radio's met dezelfde startartiest of dezelfde sfeer,
/// en meteen het volgende. Het bestand blijft staan tot "Radio afsluiten" (Saber, 21-10-2026) — weggooien
/// is "Weg", hieronder. Zie `radiosfeer.dart`.
Future<void> _pastNietInRadio(BuildContext context, Track t) async {
  final radio = context.read<RadioBesturing>();
  final sfeer = context.read<RadioSfeer>();
  final meldingen = ScaffoldMessenger.of(context);
  // Eerst het oordeel (op de pc meteen, op een toestel alvast hier), dan de radio: die vraagt het meteen na.
  final klaar = sfeer
      .zet(artiest: t.artist, titel: t.title, zaad: radio.sfeerZaad, familie: radio.familie, naar: Sfeeroordeel.pastNiet)
      .catchError((Object _) {});
  await radio.pastNiet(t);
  await klaar;
  meldingen.showSnackBar(SnackBar(
    content: Text('${t.artist} — ${t.title} past niet in deze radio. Het komt niet meer in radio\'s als deze.'),
    duration: const Duration(seconds: 3),
  ));
}

/// "Past in deze radio" — nog eens tikken haalt het oordeel weg.
Future<void> _pastInRadio(BuildContext context, Track t) async {
  final radio = context.read<RadioBesturing>();
  final sfeer = context.read<RadioSfeer>();
  final meldingen = ScaffoldMessenger.of(context);
  final was = sfeer.oordeel(artiest: t.artist, titel: t.title, zaad: radio.sfeerZaad, familie: radio.familie);
  final naar = was == Sfeeroordeel.past ? null : Sfeeroordeel.past;
  await sfeer
      .zet(artiest: t.artist, titel: t.title, zaad: radio.sfeerZaad, familie: radio.familie, naar: naar)
      .catchError((Object _) {});
  meldingen.showSnackBar(SnackBar(
    content: Text(naar == null ? 'Niet meer onthouden.' : 'Onthouden: past in deze radio.'),
    duration: const Duration(seconds: 2),
  ));
}

/// De weg uit een radio.
///
/// Een radio houdt niet vanzelf op — dat is wat hem een radio maakt. Zonder deze knop is de enige
/// manier om hem te verlaten iets ánders aanklikken, en dan komt het overzicht van wat er opgehaald
/// is als een verrassing bovenop waar je net op drukte.
class _RadioAfsluitknop extends StatelessWidget {
  const _RadioAfsluitknop();

  @override
  Widget build(BuildContext context) {
    // Een zone op afstand gekozen: dit gaat over dit toestel, niet over wat je nu ziet (zones, 21-10-2026).
    if (_misschien<GekozenZone>(context, luister: true)?.opAfstand != null) return const SizedBox.shrink();
    final radio = context.watch<RadioBesturing>();
    final p = context.watch<PlayerStore>();
    if (!radio.loopt) return const SizedBox.shrink();
    // Een radio uit een zin die zijn genoemde aantal gespeeld heeft: hier gaat hij verder.
    final gaDoor = radio.aantalOp && (p.radioDroog || p.wilVerder);
    return Padding(
      padding: const EdgeInsets.only(top: kRuimte12),
      child: Center(
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            if (gaDoor) ...[
              TextButton.icon(
                onPressed: radio.gaDoor,
                icon: const Icon(Icons.play_arrow_rounded, size: 16),
                label: const Text('Ga door'),
                style: TextButton.styleFrom(foregroundColor: _accent),
              ),
              const SizedBox(width: kRuimte8),
            ],
            TextButton.icon(
              onPressed: radio.stop,
              icon: const Icon(Icons.close_rounded, size: 15),
              label: const Text('Radio afsluiten'),
              style: TextButton.styleFrom(foregroundColor: _muted),
            ),
          ],
        ),
      ),
    );
  }
}

class NowPlayingScreen extends StatefulWidget {
  const NowPlayingScreen({super.key});

  @override
  State<NowPlayingScreen> createState() => _NowPlayingScreenState();
}

class _NowPlayingScreenState extends State<NowPlayingScreen> with SingleTickerProviderStateMixin {
  /// De wachtrij als glaspaneel rechts, op een breed scherm (Saber, 17-10-2026: "die moet trouwens ook
  /// in de now playing screen staan als ik die wil openen vanuit dit venster"). Gaat hij open, dan
  /// schuift de hoes met de cd naar links en komt het paneel rechts binnen; nog een klik schuift alles
  /// terug. Hoort bij dit scherm: het paneel naast de pagina's ([WachtrijPaneel]) blijft wat het was.
  bool _wachtrij = false;
  late final AnimationController _paneel =
      AnimationController(vsync: this, duration: const Duration(milliseconds: 380))..addListener(() => setState(() {}));

  void _wisselWachtrij() {
    setState(() => _wachtrij = !_wachtrij);
    _wachtrij ? _paneel.forward() : _paneel.reverse();
  }

  /// Twee tikken op de hoes draaien hem om; één tik vergroot (wat er voor staat). Saber koos dat op
  /// 16-10-2026. De gewone tik wacht daarvoor [kTweedeTik] — zie `ui/draaihoes.dart`.
  final _draai = DraaiHoesController();
  final _tikken = TweeTikken();
  Uint8List? _achterNu;

  /// Waar de hoes in zijn vak staat ([AlbumArt.hoesX]): het logo erboven en de plaatnaam eronder
  /// schuiven mee, naast elkaar. Onder elkaar staat alles al gecentreerd.
  final _hoesX = ValueNotifier<double>(0);

  /// Gelijk volume: de eenmalige aankondiging ("dit nummer speelt 6,2 dB zachter…"), hooguit één keer
  /// per scherm, alleen bij een VERLAGING, niet op de tv. Aflopen telt alleen als gezien als de app die
  /// twintig seconden op de voorgrond stond — anders komt hij de volgende keer terug.
  bool _aankondigingGedaan = false;
  bool _nietOpVoorgrond = false;
  AppLifecycleListener? _levensloop;

  void _misschienAankondigen(PlayerStore p) {
    if (_aankondigingGedaan || isTv) return;
    final settings = context.read<AppSettings>();
    final b = p.luidheidToegepast;
    if (settings.luidheidUitgelegd || b == null || b.db >= 0) return;
    if (luidheidsstandUit(settings.luidheid) == Luidheidsstand.uit) return;
    _aankondigingGedaan = true;
    _nietOpVoorgrond = false;
    _levensloop ??= AppLifecycleListener(onStateChange: (s) {
      if (s != AppLifecycleState.resumed) _nietOpVoorgrond = true;
    });
    final db = b.db;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      toonLuidheidAankondiging(
        context,
        db: db,
        // Staat Luider al aan, dan is een Luider-knop er een die niets doet.
        onLuider: luidheidsstandUit(settings.luidheid) == Luidheidsstand.luid
            ? null
            : () {
                settings.luidheid = 'luid';
                unawaited(settings.save());
              },
        onUit: () {
          settings.luidheid = 'uit';
          unawaited(settings.save());
        },
        opGezien: () {
          settings.luidheidUitgelegd = true;
          unawaited(settings.save());
        },
        telAfloop: () => !_nietOpVoorgrond,
      );
    });
  }

  /// De stapel (ui/wachtrij_stapel.dart): hoe ver er gebladerd is, en de pijltjes van de tv.
  final _stapel = GlobalKey<WachtrijStapelState>();
  final _stapelBesturing = StapelBesturing();

  void _opStapelKeuze() {
    if (mounted) setState(() {});
  }

  @override
  void initState() {
    super.initState();
    StapelKeuze.aan.addListener(_opStapelKeuze);
  }

  @override
  void dispose() {
    StapelKeuze.aan.removeListener(_opStapelKeuze);
    _stapelBesturing.dispose();
    _paneel.dispose();
    _levensloop?.dispose();
    _spoelPijlen.vergeet();
    _okKlok?.cancel();
    _draai.dispose();
    _tikken.dispose();
    _eersteRondje.dispose();
    _hoesX.dispose();
    super.dispose();
  }

  /// Het eerste artiestrondje vóór de naam (zie [ArtiestRondjes]): op een tv de plek waar OMHOOG
  /// vanaf de hoes naartoe gaat.
  final _eersteRondje = FocusNode(debugLabel: 'np-eerste-rondje');

  /// Loopt na een eerste OK op de hoes: komt er binnen [kTvTweedeOk] een tweede, dan draait de hoes
  /// om; anders pauzeert (of speelt) hij.
  Timer? _okKlok;

  /// OK op de hoes, op een tv. Twee keer kort na elkaar draait hem om (zoals twee tikken op een gsm);
  /// één keer pauzeert of speelt, een tel later — pas dan weet je dat er geen tweede kwam.
  void _okOpHoes(VoidCallback? speel) {
    // Gebladerd in de stapel: OK speelt wat er vooraan staat.
    if ((_stapel.currentState?.blad ?? 0) > .5) {
      _stapelBesturing.speel();
      return;
    }
    final klok = _okKlok;
    if (klok != null && klok.isActive) {
      klok.cancel();
      _okKlok = null;
      _draai.draai(heeftAchterkant: _achterNu != null);
      return;
    }
    _okKlok = Timer(kTvTweedeOk, () {
      _okKlok = null;
      speel?.call();
    });
  }

  /// Staat de markering op de hoes? Dan — en alleen dan — zijn links en rechts vorige en volgende.
  ///
  /// De voorwaarde is de hele reparatie. Links en rechts zijn op een televisie óók hoe Flutter de
  /// markering tussen knoppen verplaatst, en op dit scherm staan shuffle, spoelen, vorige, spelen,
  /// volgende, herhalen en de speakerkeuze allemaal naast elkaar in één rij. Ze onvoorwaardelijk
  /// afvangen zou zeven van de acht knoppen onbereikbaar maken — waaronder de speakerkeuze, en die
  /// is de enige weg om de muziek terug te halen als hij eenmaal in een andere kamer speelt.
  ///
  /// Op de hoes staan links en rechts alleen: daar heeft de markering geen buren, dus daar doen ze
  /// vandaag aantoonbaar niets. Er wordt dus niets afgenomen.
  bool _opHoes = false;
  /// The sleeve the AlbumArt below settled on, so enlarging it shows THAT image.
  ///
  /// The zoom used to open the player's own cover, which is captured when a track starts and knows
  /// nothing about the pressing this screen resolved — so clicking the art you were looking at
  /// produced a different, older one.
  Uint8List? _shown;

  @override
  Widget build(BuildContext context) {
    final x = _Transport(context);
    final p = x.player;
    final t = x.track;
    final cast = x.speaker;
    final casting = x.casting;
    if (!casting && p is PlayerStore) _misschienAankondigen(p);
    final position = x.position;
    final duration = x.duration;
    final playing = x.playing;
    final prog = x.progress;
    // Uit de speler, niet uit dit scherm. Die rekent hem één keer per plaat uit, en de spelerbalk
    // onderaan gebruikt exact dezelfde — zie [PlayerStore.wasKleur].
    final was = kleurWas(wasBasis(p.wasKleur));
    // Naast elkaar of gestapeld? De rekensom staat in `ui/speelvlak.dart`, want die is zonder
    // speler, bibliotheek en speaker na te rekenen — en dit scherm is dat niet.
    final schermmaat = MediaQuery.sizeOf(context);
    final naast = naastElkaar(scherm: schermmaat, compact: isCompact(context), tv: isTv);
    // Een telefoon dwars: breder dan hoog, maar te laag om naast elkaar te staan — zie [liggend].
    // Dan de hoes links, de kolom met titel en knoppen rechts.
    final dwars = !naast && liggend(scherm: schermmaat, tv: isTv);
    final rand = MediaQuery.paddingOf(context);
    final bruikbaar = Size(schermmaat.width - rand.horizontal, schermmaat.height - rand.vertical);
    // Naast elkaar of dwars: in allebei staat de tekst links uitgelijnd naast de hoes.
    final zij = naast || dwars;
    // Gestapeld (gsm, iPad staand, een smal pc-venster) en geen tv: daar staat de artiest één keer,
    // bovenaan met zijn foto, en de kwaliteit boven de afspeelbalk (Saber, 19-10-2026).
    final gestapeld = !zij && !isTv;
    // Hoe breed het wachtrijpaneel nu is (schuivend tussen 0 en [kNuSpeeltWachtrij]); de hoes rekent
    // met wat er naast het paneel overblijft.
    final paneelBreedte = naast ? Curves.easeOutCubic.transform(_paneel.value) * kNuSpeeltWachtrij : 0.0;
    // De stapel ([WachtrijStapel]) steekt links en boven uit: de hoes is dan kleiner, zodat alles in
    // dezelfde ruimte past. Niet dwars: daar is geen hoogte voor wat erboven uitsteekt.
    final stapelAan = StapelKeuze.aan.value && !dwars;
    final hoesMaatVol = naast
        ? hoesNaast(
            scherm: Size(schermmaat.width - paneelBreedte, schermmaat.height),
            reisfactor: discTravelFactor(context))
        : dwars
            ? hoesLiggend(bruikbaar: bruikbaar)
            : _sleeve(context);
    final hoesMaat = stapelAan ? hoesMaatVol / (1 + kStapelBoven) : hoesMaatVol;
    final kolom = naast
        ? kSpeelKolom
        : dwars
            ? kolomLiggend(bruikbaar: bruikbaar, hoes: hoesMaat)
            : dialogWidth(context, 540);

    // De plaat waar dit nummer op staat, één keer opgezocht.
    //
    // Dit stond binnen een `Builder` in het hoesblok, en werd daarmee alleen door de hoes gebruikt.
    // De artiestenkop erboven en de albumnaam eronder hebben hem net zo goed nodig, en drie keer
    // dezelfde vraag stellen is drie kansen om drie verschillende antwoorden te krijgen.
    final bib = context.watch<LibraryStore>();
    final al = t == null ? null : bib.albumForPath(t.path);
    // En die van het VOLGENDE nummer, om de hoes, de cd en het artiestlogo alvast klaar te zetten —
    // met dezelfde regels als hierboven, anders zet het klaarzetten iets anders klaar dan er straks
    // komt. Saber, 10-10-2026: "een lichte verspringing als je naar het volgende liedje gaat".
    final volgendNummer = p.volgendNummer;
    final volgendAlbum = volgendNummer == null ? null : bib.albumForPath(volgendNummer.path);

    // De hoes met de draaiende plaat, één keer beschreven. Hij staat in beide indelingen, en
    // twee kopieën van zeventig regels zouden binnen een maand uit elkaar lopen.
    final hoesBlok = Pressable(
      // Op tv is de hoes de rustplek: hier landt de markering bij openen, OK pauzeert,
      // en links/rechts zijn vorige en volgende. Uitvergroten is een muisgebaar — er
      // hoort een vergrootglas-cursor bij — en verhuist daarom naar een lange druk.
      autofocus: isTv,
      // Op een tv niet het hele blok met de cd erbij oplichten: alleen de hoes groeit
      // ([AlbumArt.uitgelicht]). "De cd in de hoes moet niet selecteerbaar zijn" (Saber, 16-10-2026).
      scaleOnFocus: !isTv,
      ringOnFocus: !isTv,
      onFocusChange: (v) {
        if (v != _opHoes) setState(() => _opHoes = v);
        if (!v) _spoelPijlen.vergeet();
      },
      // What the sleeve is actually drawing wins; the player's snapshot is only the
      // fallback for a track whose art has not resolved yet.
      onPressed: isTv
          ? (t == null ? null : () => _okOpHoes(casting ? cast.playPause : p.playPause))
          : ((_shown ?? p.currentCover) == null
              ? null
              // Vergroot wat er voor staat: de achterkant als je hem omdraaide.
              : () => _tikken.enkel(() {
                    if (!mounted) return;
                    final achter = _draai.omgedraaid ? _achterNu : null;
                    showDialog(
                        context: context,
                        builder: (_) => _ZoomView(achter ?? (_shown ?? p.currentCover)!));
                  })),
      onLongPress: isTv && (_shown ?? p.currentCover) != null
          ? () => showDialog(
              context: context, builder: (_) => _ZoomView((_shown ?? p.currentCover)!))
          : null,
      borderRadius: BorderRadius.circular(10),
      child: MouseRegion(
        cursor: (_shown ?? p.currentCover) == null
            ? MouseCursor.defer
            : SystemMouseCursors.zoomIn,
        // De grote schaduw hoort bij de voorkant (met de cd ernaast). Staat de achterkant voor, dan
        // draagt die zijn eigen schaduw in zijn eigen vorm: een cd-achterkant is breder dan hoog, en
        // onder hem lag anders een donkere strook (16-10-2026).
        child: ValueListenableBuilder<bool>(
          valueListenable: _draai.voorInRust,
          // Alleen onder de hoes zelf (hoesMaat × hoesMaat, linksboven), niet onder het hele blok: dat is
          // ook het vak dat voor de uitschuivende cd vrijgehouden wordt, en staat de cd niet uit, dan
          // lag er een grijs (licht) of zwart (donker) blok tot ver rechts naast de hoes (pc, 18-10-2026).
          // Met een plaat ernaast tekent [AlbumArt] de schaduw zelf ([AlbumArt.hoesSchaduw]), want
          // daar schuift de hoes; dit is voor de kale hoes zonder nummer.
          builder: (_, rust, kind) => Stack(clipBehavior: Clip.none, children: [
            if (t == null)
            Positioned(
              key: const ValueKey('np-hoes-schaduw'),
              left: 0,
              top: 0,
              width: hoesMaat,
              height: hoesMaat,
              child: IgnorePointer(
                child: AnimatedContainer(
                  duration: const Duration(milliseconds: 180),
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(16),
                    boxShadow: [
                      BoxShadow(
                          // Op licht een derde: 50 % zwart was naast de hoes een grijze vlek (gsm, 18-10-2026).
                          color: Colors.black.withValues(alpha: rust ? (Thema.licht ? .18 : .5) : 0),
                          blurRadius: 44,
                          offset: const Offset(0, 22))
                    ],
                  ),
                ),
              ),
            ),
            kind!,
          ]),
          // Same sleeve-and-disc as the album page, at the size this screen deserves.
          // The album is taken from the track that is playing, so the disc that comes
          // out is the one this song is actually on.
          child: t == null
              ? Hero(tag: kNuSpeeltHoes, child: cover(p.currentCover, size: hoesMaat, radius: 16))
              : Builder(builder: (context) {
                  // De plaat (`al`) komt van boven in `build` — zie daar waarom hij niet meer hier
                  // wordt opgezocht. Ask the library which album this track is on, rather than
                  // resolving the record again from its artist and title. Without it this screen did
                  // its own Discogs lookup and showed a different artist's album that shared a
                  // title, while the album page had the right one pinned.
                  return AlbumArt(
                    artist: al?.artist ?? t.artist,
                    album: al?.title ?? t.album,
                    // Het spelende nummer eerst: is dit een verzamelrip, dan de hoes van zijn originele
                    // uitgave (zie CoverEnricher.digitaleVoorkant).
                    titels: [t.title, if (al != null) for (final x in al.tracks) if (x.title != t.title) x.title],
                    identity: al == null ? '' : bib.uidOf(al),
                    size: hoesMaat,
                    reisFactor: dwars ? kLiggendReis : null,
                    fallback: p.currentCover,
                    chosen: al?.correctedCover,
                    trackCount: al?.tracks.length ?? 0,
                    // **Dezelfde persing als op de albumpagina, en dat is hier het hele punt.**
                    //
                    // Dit scherm kent alleen het aantal BESTANDEN dat je hebt, en dat stuurde de
                    // zoektocht een andere kant op dan de albumpagina, die het aantal van de
                    // officiële uitgave kent. Bij één nummer van een plaat van veertien kwam daar
                    // een promo-persing uit met een sticker op het doosje. Zie
                    // [persingUitHerkomst] voor het hele verhaal.
                    pinned: al == null
                        ? null
                        : bib.pinnedRelease(al) ?? persingUitHerkomst(al.resolvedFrom).release,
                    // En de uitgave uit de bekende feiten, zoals de albumpagina en de warmer: zonder
                    // zocht dit scherm in een andere map dan waar de scans liggen. Zie
                    // [albumArtVooruit].
                    pinnedMbid: al == null ? null : albumArtVooruit(bib, al).pinnedMbid,
                    roles: al == null
                        ? const {}
                        : bib.albumArtRoles(al.artist, al.title),
                    // Out and spinning while a speaker has it too. This device is
                    // deliberately silent then, so p.playing is false — but the record
                    // IS playing, just somewhere else, and that is what you came to
                    // this screen to look at.
                    playing: p.playing || context.watch<SpeakerTarget>().isCasting,
                    onFront: (f) {
                      if (mounted && !identical(f, _shown)) {
                        setState(() => _shown = f);
                      }
                    },
                    draai: _draai,
                    uitgelicht: isTv && _opHoes,
                    onAchter: (b) => _achterNu = b,
                    achterSchaduw: kNuSpeeltAchterSchaduw,
                    hoesX: _hoesX,
                    // Dezelfde als de kale hoes hierboven ('np-hoes-schaduw'), maar hij schuift mee.
                    hoesSchaduw: BoxShadow(
                        color: Colors.black.withValues(alpha: Thema.licht ? .18 : .5),
                        blurRadius: 44,
                        offset: const Offset(0, 22)),
                    kantel: isTv
                        ? KantelBron.selectie
                        : _isDesktop
                            ? KantelBron.muis
                            : KantelBron.toestel,
                    // Naast elkaar en gestapeld; niet dwars (daar staat de plaatnaam vlak onder de hoes).
                    // Gestapeld ligt de titel eroverheen, en dat mag: met een eigen vak ervoor stond er
                    // een gat tussen hoes en titel (Saber, 19-10-2026: "dan zit de tekst in de schaduw
                    // maar dat geeft niet … tis nie mooi zo").
                    // In de stapel wijkt hij (Saber, 19-10-2026): daar staan de volgende hoezen.
                    // Ook op een tv, net als op de albumpagina (19-10-2026, "zoals op pc en gsm").
                    spiegel: !dwars && !stapelAan,
                    // De hoes van de minispeler groeit hierheen uit (zie [kNuSpeeltHoes]).
                    heroTag: kNuSpeeltHoes,
                    // De hoes en cd van het volgende nummer alvast klaarzetten — anders staat er bij
                    // de wissel even de hoes uit het bestand met een getekende schijf.
                    volgende: volgendAlbum == null ? null : albumArtVooruit(bib, volgendAlbum),
                  );
                }),
        ),
      ),
    );

    // Twee tikken draaien de hoes om; niet op een tv (daar is OK afspelen en pauzeren).
    final hoesMetTikken = isTv
        ? hoesBlok
        : DubbelTikVlak(
            tikken: _tikken,
            onDubbel: () => _draai.draai(heeftAchterkant: _achterNu != null),
            child: hoesBlok,
          );

    // De wachtrij als stapel (Saber, 19-10-2026; ⋯-menu): de hoes met de cd vooraan, wat hierna komt
    // erachter. Een tik op een gebladerde hoes springt ernaartoe, zoals een tik in de wachtrijlijst.
    final hoesOfStapel = !stapelAan || t == null
        ? hoesMetTikken
        : WachtrijStapel(
            key: _stapel,
            maat: hoesMaat,
            blok: hoesMaat * (1 + discTravelFactor(context)),
            voorste: hoesMetTikken,
            volgende: volgendeHoezen(p, bib),
            onSpeel: (n) =>
                p.springNaar(p.currentIndex + n),
            x: _hoesX,
            onWeg: isTv ? null : () => Navigator.of(context).maybePop(),
            besturing: _stapelBesturing,
          );

    // De hoes met de artiest erboven en de plaat eronder.
    //
    // **Waarom dit één kolom is en niet twee keer los.** Het hoesblok staat in beide indelingen, en
    // dat staat er bij [hoesBlok] al als waarschuwing: twee kopieën lopen binnen een maand uit
    // elkaar. Dat geldt voor wat eromheen komt net zo goed.
    //
    // **Waarom niet op televisie.** De hoogte is daar al krap tot op de punt — zie de rekensom bij
    // [_sleeve]: op de Shield kwam deze kolom eens 80 punten te lang uit, en die 80 vielen weg bij
    // de rij met vorige, afspelen en volgende. Er is geen hoogte om weg te geven, en een logo boven
    // de hoes is op anderhalve meter afstand ook geen winst.
    final artiestVanPlaat = al?.artist ?? t?.artist ?? '';
    final albumNaam = (al?.title ?? t?.album ?? '').trim();
    // Wie er bovenaan staat: onder de titel komt dan alleen wie er nog bij hoort ([gastenNaastKop]).
    final kopNamen = artiestVanPlaat.trim().isEmpty ? const <String>[] : [...kopFotoNamen(artiestVanPlaat), artiestVanPlaat];
    // Naast elkaar staan het logo en de plaatnaam op de breedte van de hoes, en dus horen ze met de
    // hoes mee te schuiven als die naar het midden van zijn vak gaat (zie [hoesEnSchijfX]).
    Widget metDeHoes(Widget kind) => !zij || t == null
        ? kind
        : ValueListenableBuilder<double>(
            valueListenable: _hoesX,
            // In de stapel staat de hoes een stuk naar rechts (wat links uitsteekt).
            builder: (_, x, k) => Transform.translate(offset: Offset(x + (stapelAan ? hoesMaat * kStapelLinks : 0), 0), child: k),
            child: kind,
          );
    final hoesKolom = isTv
        ? hoesOfStapel
        : Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment:
                zij ? CrossAxisAlignment.start : CrossAxisAlignment.center,
            children: [
              // Dwars niet: op 384 punten hoog is er voor een logo boven de hoes geen plaats.
              if (!dwars && artiestVanPlaat.trim().isNotEmpty) ...[
                metDeHoes(kopMetFoto(
                  gestapeld,
                  kopFotoNamen(artiestVanPlaat),
                  ArtiestKop(
                    naam: artiestVanPlaat,
                    // Zelfde regel als [artiestVanPlaat], voor het volgende nummer.
                    volgende: volgendAlbum?.artist ?? volgendNummer?.artist,
                    // Met de foto ernaast staan logo en naam links tegen de foto; het geheel staat in het midden.
                    gecentreerd: !zij && !gestapeld,
                    // Naast elkaar de breedte van de HOES, niet die van de tekstkolom ernaast: dan
                    // staat de kop netjes boven de plaat waar hij over gaat. De loopruimte van de cd
                    // zit in het blok maar niet onder de hoes zelf. Gestapeld gaat de foto ervan af.
                    breedte: zij ? hoesMaat : dialogWidth(context, 540) - (gestapeld ? kKopFoto + 10 : 0),
                  ),
                )),
                const SizedBox(height: 14),
              ],
              // Gestapeld (gsm en iPad staand) staat de plaatnaam BOVEN de hoes, onder de artiest: eronder
              // komt de spiegeling (Saber, 19-10-2026, "plaatnaam boven de hoes").
              if (!zij && albumNaam.isNotEmpty) ...[
                SizedBox(width: dialogWidth(context, 540), child: _albumRegel(context, albumNaam, al)),
                const SizedBox(height: 12),
              ],
              hoesOfStapel,
              if (zij && albumNaam.isNotEmpty) ...[
                const SizedBox(height: 12),
                metDeHoes(SizedBox(
                  width: hoesMaat,
                  child: _albumRegel(context, albumNaam, al, gecentreerd: false),
                )),
              ],
            ],
          );

    // Alles onder de hoes: titel, artiest, spoelbalk, transport, speakervolume. Als lijst en
    // niet als widget, zodat hij in de gestapelde indeling gewoon in de kolom valt en naast
    // elkaar in de kolom ernaast — zonder een tussenlaag die de hoogte anders zou verdelen.
    final onder = <Widget>[
      // Eén regel op tv, met puntjes. Een titel die naar twee regels loopt kost er 40
      // bij, en dat is precies wat er niet is — op 540 punten is dit scherm 80 te lang.
      Text(t?.title ?? '—',
          maxLines: isTv ? 1 : null,
          overflow: isTv ? TextOverflow.ellipsis : null,
          style: const TextStyle(fontSize: 25, fontWeight: FontWeight.w800), textAlign: zij ? TextAlign.left : TextAlign.center),
      const SizedBox(height: 6),
      // **Waarom hier een breedte omheen staat.** Deze rij had er geen, en dat is precies waarom de
      // artiestenregel aan twee kanten van het scherm afliep zonder puntjes.
      //
      // `ArtistNames` is een `Row` met `Flexible`-kinderen — gebouwd om in te korten. Maar
      // `Flexible` doet alleen iets als zijn `Row` een begrensde breedte krijgt, en `ArtistLine`
      // stond hier als NIET-flexibel kind in deze rij. Zo'n kind krijgt in Flutter een onbegrensde
      // breedte mee, dus kreeg `ArtistNames` daarbinnen oneindig, had `Flexible` niets om tegenaan
      // te duwen, en werden de namen op volle breedte getekend — gecentreerd, dus links én rechts
      // eraf. Gemeld op "At The Villa People · Etienne Vandewiele · Bruno Quatresous".
      //
      // Dezelfde maat als de spoelbalk eronder: één breedte voor dit hele blok, geen nieuw getal.
      SizedBox(
        width: kolom,
        // De rij zelf staat in [NuSpeeltNaamrij] (luidheid_keuze.dart), zodat hij zonder speler te
        // toetsen is. Het gelijk-volume-merk krijgt op een smal scherm een eigen regel eronder — in
        // de rij zou het de artiestnaam wegdrukken — en staat op de tv en brede schermen ernaast.
        child: NuSpeeltNaamrij(
          zij: zij,
          merkInDeRij: !merkEigenRegel(kolom: kolom, tv: isTv),
          // Flexibel (dat doet de rij), zodat de begrenzing hierboven ook echt bij de namen aankomt.
          // En omvouwend, want hier is ruimte: drie gasten zakken naar een tweede regel in plaats
          // van tot puntjes te worden teruggebracht.
          naam: t == null
              ? null
              : ArtistLine(
                  artist: t.artist,
                  title: t.title,
                  lookup: true,
                  omvouwen: true,
                  style: TextStyle(color: _muted, fontSize: 15),
                  // De artiesten als rondjes vóór hun naam, elk naar hun pagina (Saber, 17-10-2026).
                  // Gestapeld staat de foto al bovenaan, en hier alleen wie er nog bij komt.
                  rondjes: !gestapeld,
                  eersteRondje: gestapeld ? null : _eersteRondje,
                  alNoemd: gestapeld ? kopNamen : null,
                ),
          echtheid: gestapeld || t == null ? null : _echtheidMerk(t),
          // Wat je NU hoort, en niet wat er op de schijf van de pc staat. Zie [_stroomKwaliteit]:
          // onderweg stuurt je pc een kleinere versie, en zolang de badge het bestand toonde was
          // er geen enkele manier om te zien dát dat gebeurde. Gestapeld staat hij boven de afspeelbalk.
          kwaliteit: !gestapeld && t != null && t.sizeBytes > 0 ? _qualityBadge(_stroomKwaliteit(p, t)) : null,
          merk: gestapeld || t == null ? null : _luidheidMerk(context, p, t, cast),
        ),
      ),
      // Twee regels die hier ontbraken, en allebei om dezelfde reden: dit scherm dekt op een
      // telefoon de spelerbalk af, en die balk was de ENIGE plek waar ze stonden. Wie hier kijkt
      // omdat er geen geluid komt, kreeg dus niets te zien — geen fout, geen uitleg, alleen 0:00.
      if (p.speelFout != null) ...[
        const SizedBox(height: kRuimte8),
        SizedBox(
          width: kolom,
          child: Text(p.speelFout!,
              textAlign: zij ? TextAlign.start : TextAlign.center,
              style: TextStyle(color: leesbaar(const Color(0xFFE0A33A)), fontSize: 12.5)),
        ),
      // De radio: wat hij doet als er niets klinkt (zoekt, het genoemde aantal is er), en "opnieuw" bij
      // een herhaling. In hetzelfde vak als de melding hierboven en niet op een eigen regel: de gestapelde
      // indeling (telefoon staand, de Shield) heeft geen schuifvangnet, en op de tv is de hoogte tot op de
      // punt verdeeld — een regel erbij duwde "Radio afsluiten" onder de rand (beoordeling van 08-10-2026).
      ] else if ((p.radioMode ? _radioRegel(context, p) : null) case final status?) ...[
        const SizedBox(height: kRuimte8),
        SizedBox(
          width: kolom,
          child: Text(status,
              textAlign: zij ? TextAlign.start : TextAlign.center,
              style: TextStyle(color: _accent2, fontSize: 12.5)),
        ),
      ] else if (p.speeltHerhaling) ...[
        const SizedBox(height: kRuimte8),
        SizedBox(
          width: kolom,
          child: Text('Opnieuw — dit nummer speelde eerder in deze radio',
              textAlign: zij ? TextAlign.start : TextAlign.center,
              style: TextStyle(color: kGedempt, fontSize: 11.5)),
        ),
      ],
      // Geen uitleg meer over wat de pc onderweg stuurt ("Onderweg: je pc stuurt 16/44.1 in plaats van
      // 24/192 …"): het merk naast de artiest zegt al wat je hoort, en de zin nam twee regels (Saber,
      // 19-10-2026: "al die uitleg hoeft niet eigenlijk, pakt veel plaats in").
      //
      // Gestapeld: kwaliteit en volume in het midden, vlak boven de afspeelbalk (Saber, 19-10-2026:
      // "de kwaliteit gecentreerd boven de afspeelbalk").
      if (gestapeld && t != null) ...[
        const SizedBox(height: 22),
        SizedBox(
          key: const ValueKey('np-kwaliteitsregel'),
          width: kolom,
          // De badge opent het kwaliteitsblad (wat je nu hoort, wat het bestand echt is, gelijk volume);
          // de volumezin zelf staat daar en niet meer hier, en de streamknop staat ernaast in plaats van in
          // de bedieningsrij (Saber, 20-10-2026: "playbar is te vol zo").
          child: KwaliteitsRegel(
            echtheid: _echtheidMerk(t),
            kwaliteit: t.sizeBytes > 0 ? _kwaliteitKnop(context, p, t, cast) : null,
            naast: const _SpeakerButton(iconSize: 22),
          ),
        ),
        const SizedBox(height: 10),
      ] else
        SizedBox(height: isTv ? 14 : 26),
      SizedBox(
        width: kolom,
        child: Row(
          children: [
            Text(_fmt(position), style: TextStyle(color: _muted, fontSize: 12)),

            Expanded(
              child: SliderTheme(
                data: SliderTheme.of(context).copyWith(
                  trackHeight: 4,
                  thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 7),
                  activeTrackColor: _accent,
                  inactiveTrackColor: kLijn,
                  thumbColor: kFel,
                ),
                // Same as the player bar's: a Slider eats left and right to change its
                // value, so the highlight would enter the seek bar and never leave it.
                child: _maybeFocusable(Slider(
                  value: prog,
                  // Dragging is carried locally and sent once on release: a seek per pixel
                  // would flood an embedded stack and land behind where you let go.
                  onChanged: duration.inMilliseconds == 0 || (!casting && t == null)
                      ? null
                      : casting
                          ? (v) => cast.scrubTo(duration * v)
                          : (v) => p.seek(duration * v),
                  onChangeEnd:
                      casting && duration.inMilliseconds > 0 ? (v) => cast.seekTo(duration * v) : null,
                )),
              ),
            ),
            Text(_fmt(duration), style: TextStyle(color: _muted, fontSize: 12)),
          ],
        ),
      ),
      // Where it is actually coming out, when that is not here. No fake progress bar
      // above it: the position lives on the speaker and this device does not know it, so
      // a bar that crawled along on a guess would be a lie you could watch.
      Builder(builder: (context) {
        final target = context.watch<SpeakerTarget>();
        if (!target.isCasting) return const SizedBox(height: 8);
        // Een reden gaat vóór de geruststelling. "Speelt op Huiskamer" boven een stille
        // kamer is precies de melding die je een half uur laat zoeken; als de pc weet
        // waarom er niets klinkt, hoort dat hier te staan en niet in een logbestand.
        final probleem = target.probleem;
        if (probleem != null) {
          return Padding(
            padding: const EdgeInsets.only(top: 4, bottom: 4),
            child: Row(mainAxisAlignment: zij ? MainAxisAlignment.start : MainAxisAlignment.center, children: [
              const Icon(Icons.volume_off_rounded, size: 16, color: Colors.orangeAccent),
              const SizedBox(width: 8),
              Flexible(
                child: Text(probleem,
                    maxLines: 3,
                    style: const TextStyle(color: Colors.orangeAccent, fontSize: 13.5)),
              ),
            ]),
          );
        }
        return Padding(
          padding: const EdgeInsets.only(top: 4, bottom: 4),
          child: Row(mainAxisAlignment: zij ? MainAxisAlignment.start : MainAxisAlignment.center, children: [
            Icon(Icons.speaker_rounded, size: 16, color: _accent),
            const SizedBox(width: 8),
            Flexible(
              child: Text('Speelt op ${target.device!.name}',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: TextStyle(color: _accent, fontSize: 13.5)),
            ),
          ]),
        );
      }),
      // De duimen. Alleen bij een nummer dat DEZE radio heeft opgehaald — zie [_RadioOordeel].
      _RadioOordeel(track: t, naast: zij),
      // Krimpen als het niet past: met de wachtrijknop erbij is de rij ~400 punten, en een telefoon
      // heeft er na de marges minder. Op een breed scherm staat hij gewoon op ware grootte.
      Align(
        alignment: zij ? Alignment.centerLeft : Alignment.center,
        child: FittedBox(
        fit: BoxFit.scaleDown,
        child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          // Gestapeld (de gsm): links een onzichtbare kopie van de wachtrijknop rechts, zodat de afspeelknop
          // precies in het midden staat (Saber, 20-10-2026: "centreer de playbar").
          if (gestapeld) ...[
            const Visibility(
              visible: false,
              maintainSize: true,
              maintainAnimation: true,
              maintainState: true,
              child: _WachtrijKnop(maat: 24),
            ),
            const SizedBox(width: 8),
          ],
          IconButton(
              icon: ShuffleIcoon(aan: p.shuffle, maat: 24),
              iconSize: 24,
              color: p.shuffle ? _accent : _muted,
              onPressed: p.toggleShuffle),
          const SizedBox(width: 8),
          // Geen ±10-knoppen op een tv meer (16-10-2026, "te druk"): links en rechts ingedrukt
          // houden op de hoes spoelt (zie [_pijlAlsNummerknop]).
          DuwKnop(
              icoon: Icons.skip_previous_rounded,
              richting: -1,
              maat: 34,
              kleur: _text,
              // Door `_Transport` en niet met een eigen `?? false`.
              //
              // Deze twee knoppen herhaalden de oude logica die grijs werd zodra de
              // speaker één poll zweeg — terwijl de muziek doorliep en dezelfde knop in de
              // spelerbalk het wél deed. `x.previous` valt terug op de eigen wachtrij; dat
              // is precies waar die helper voor gemaakt is.
              onPressed: x.previous),
          const SizedBox(width: 8),
          Container(
            decoration: BoxDecoration(color: kFel, shape: BoxShape.circle),
            child: IconButton(
              // De markering start op tv niet hier maar op de HOES. Dat was ooit deze
              // knop, maar die stond op de Shield 80 punten onder de schermrand — dus
              // begon het scherm met een ring die je niet kon zien. De hoes staat altijd
              // in beeld, en van daaruit zijn links en rechts vorige en volgende.
              icon: SpeelPauzeIcoon(speelt: playing, maat: 40),
              color: _bg,
              iconSize: 40,
              onPressed: casting ? cast.playPause : (t == null ? null : p.playPause),
            ),
          ),
          const SizedBox(width: 8),
          DuwKnop(icoon: Icons.skip_next_rounded, maat: 34, kleur: _text, onPressed: x.next),
          const SizedBox(width: 8),
          // Shuffle and repeat stay local on purpose: the speaker plays the queue the PC
          // hands it one track at a time, so changing the order here would take effect on
          // whatever is sent NEXT and look like it did nothing now.
          IconButton(
              icon: HerhaalIcoon(
                  stand: p.repeat,
                  icoon: p.repeat == RepeatMode.one ? Icons.repeat_one_rounded : Icons.repeat_rounded,
                  maat: 24),
              iconSize: 24,
              color: p.repeat == RepeatMode.off ? _muted : _accent,
              onPressed: casting ? null : p.cycleRepeat),
          // De wachtrij naast de hoes, op een breed scherm. Het icoon van Afspeellijsten: de regels
          // schuiven binnen als het paneel opengaat.
          if (naast) ...[
            const SizedBox(width: 8),
            IconButton(
              key: const ValueKey('np-wachtrij'),
              tooltip: _wachtrij ? 'Wachtrij sluiten' : 'Wachtrij',
              iconSize: 24,
              icon: MenuIcoon(
                soort: MenuIcoonSoort.afspeellijsten,
                kleur: _wachtrij ? _accent : _muted,
                gekozen: _wachtrij,
                maat: 24,
              ),
              onPressed: _wisselWachtrij,
            ),
          ] else if (!isTv) ...[
            // Op een telefoon past het paneel er niet naast: dan dezelfde lijst als blad van onderen,
            // zoals vanuit de minispeler. Daarvoor stond er in Nu speelt geen wachtrijknop
            // (S26, 18-10-2026; Saber: "die moet ook in de now playing screen staan").
            const SizedBox(width: 8),
            const _WachtrijKnop(maat: 24),
          ],
          // Gestapeld staat de streamknop naast de kwaliteit (zie [KwaliteitsRegel]).
          if (!gestapeld) ...[
            const SizedBox(width: 12),
            const _SpeakerButton(iconSize: 24),
          ],
          // Op een tv staat de bovenste rij met ⋯ er niet (48 punten die er niet zijn), en lang OK op de
          // hoes is uitvergroten. Hetzelfde menu dan hier, achteraan, met de keuze voor de stapel
          // (Shield, 19-10-2026: de stapel was op de tv niet aan te zetten; Saber: "ook op tv").
          if (isTv && t != null) ...[
            const SizedBox(width: 12),
            Builder(
              builder: (knopContext) => TvLabelled(
                label: 'Meer',
                child: IconButton(
                  key: const ValueKey('np-meer-tv'),
                  icon: const Icon(Icons.more_horiz_rounded, size: 24),
                  tooltip: 'Meer',
                  color: _muted,
                  onPressed: () => _toonItemMenu(knopContext, _metStapelKeuze(_nummerMenu(knopContext, t))),
                ),
              ),
            ),
          ],
        ],
      ),
      ),
      ),
      // The speaker's own volume, and only when it says it has one. A Sonos and the KEF
      // both do; a renderer without RenderingControl simply shows nothing here rather
      // than a slider that moves and changes nothing.
      if (casting && cast.hasVolume)
        Padding(
          padding: const EdgeInsets.only(top: 6),
          child: SizedBox(
            width: dialogWidth(context, 320),
            child: Row(
              children: [
                // The slider is ExcludeFocus on a television — left and right would be
                // eaten by it — so without these two the speaker's volume cannot be
                // touched at all from the couch. The TV remote's own volume keys go to
                // the television, not to a UPnP speaker in another room.
                if (isTv)
                  TvLabelled(
                    label: 'Zachter',
                    child: IconButton(
                    icon: const Icon(Icons.volume_down_rounded, size: 22),
                    color: _muted,
                    tooltip: 'Zachter',
                    onPressed: () => cast.setVolume((cast.volume - 5).clamp(0, 100)),
                  ),
                  )
                else
                  Icon(Icons.volume_down_rounded, size: 19, color: _muted),
                Expanded(
                  child: SliderTheme(
                    data: SliderTheme.of(context).copyWith(
                      trackHeight: 3,
                      thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 6),
                      activeTrackColor: _accent,
                      inactiveTrackColor: kLijn,
                      thumbColor: kFel,
                    ),
                    child: _maybeFocusable(Slider(
                      value: cast.volume.clamp(0, 100).toDouble(),
                      max: 100,
                      onChanged: (v) => cast.setVolume(v.round()),
                    )),
                  ),
                ),
                if (isTv)
                  TvLabelled(
                    label: 'Harder',
                    child: IconButton(
                    icon: const Icon(Icons.volume_up_rounded, size: 22),
                    color: _muted,
                    tooltip: 'Harder',
                    onPressed: () => cast.setVolume((cast.volume + 5).clamp(0, 100)),
                  ),
                  )
                else
                  Icon(Icons.volume_up_rounded, size: 19, color: _muted),
                const SizedBox(width: 6),
                SizedBox(
                  width: 30,
                  child: Text('${cast.volume}',
                      textAlign: TextAlign.right,
                      style: TextStyle(color: _muted, fontSize: 12)),
                ),
              ],
            ),
          ),
        ),
      // Een zone op afstand gekozen: het volume van de app daar (Saber, 21-10-2026: "volume van de app").
      if (x.afstand case final zone? when zone.heeftVolume)
        Padding(
          padding: const EdgeInsets.only(top: 6),
          child: SizedBox(width: dialogWidth(context, 320), child: _ZoneVolume(zone: zone)),
        ),
      // Onderaan, en alleen tijdens een radio: de weg eruit.
      //
      // **Waarom die knop er hoort te zijn.** Een radio houdt niet vanzelf op — dat is precies wat
      // hem een radio maakt. Zonder deze knop is de enige manier om hem te verlaten iets ánders
      // aanklikken, en dan komt het overzicht van wat er opgehaald is als een verrassing bovenop
      // waar je net op drukte.
      const _RadioAfsluitknop(),
    ];

    return Scaffold(
      backgroundColor: _bg,
      // Toetsen bubbelen vanaf de gefocuste knop hierheen. `canRequestFocus: false` en
      // `skipTraversal: true`, want dit mag géén extra stop in de markering worden — het kijkt
      // alleen mee. Deze route ligt bovenop, dus lijsten, rasters en de rail eronder zien hem nooit.
      // NAAR BENEDEN VEGEN SLUIT HET SCHERM.
      //
      // De sluitknop hierboven is een pijl naar beneden, en tot nu toe deed alleen die knop iets:
      // er was geen enkel gebaar om dit scherm weg te vegen, terwijl dat de gebarentaal is die
      // iedereen van een muziekapp kent. De route komt nu ook van onderen, dus het gebaar en de
      // beweging horen bij elkaar.
      //
      // Op de snelheid en niet op de afstand: een korte, besliste veeg moet net zo goed werken als
      // een lange trage. Niet op een televisie — daar is geen vinger, en daar doet BACK dit al.
      body: GestureDetector(
        onVerticalDragEnd: isTv
            ? null
            : (d) {
                if ((d.primaryVelocity ?? 0) > 320) Navigator.of(context).maybePop();
              },
        child: Focus(
        canRequestFocus: false,
        skipTraversal: true,
        onKeyEvent: (_, e) => _pijlAlsNummerknop(e, x),
        child: Stack(
        children: [
          // **De kleur van de hoes, achter alles.**
          //
          // Hiervoor lag er alleen een uitvergrote, doorzichtige hoes over het hele scherm met een
          // vlakke waas van 50% erbovenop. Dat gaf onderaan — waar de tijdbalk en de knoppen staan —
          // een uitgesmeerde foto in plaats van een rustige ondergrond, en het had niets te maken
          // met de kleur die de albumpagina van dezelfde plaat al gebruikt.
          //
          // Nu hetzelfde verloop als daar: de tint bovenaan, de gewone achtergrond onderaan. En
          // overvloeiend, want dit scherm wisselt van plaat terwijl je ernaar kijkt.
          if (was != null)
            Positioned.fill(
              child: IgnorePointer(
                child: AnimatedContainer(
                  duration: kWas,
                  curve: Curves.easeOut,
                  decoration: BoxDecoration(gradient: was),
                ),
              ),
            ),
          // De stilstaande kleurvlekken van de hoes (Saber, 18-10-2026: "achter Nu speelt en de balk"):
          // zachte ronde vlekken in de kleuren van de plaat, waar ze op de hoes liggen. Ze bewegen
          // niet ("Nu speelt-achtergrond stilstaand") en worden één keer getekend.
          Positioned.fill(child: HoesVlekkenLaag(p.hoesVlekken, sterkte: kNuSpeeltVlekken)),
          // De hoes zelf blijft erachter staan, maar dooft naar onderen uit — anders ligt hij nog
          // steeds over de knoppen heen.
          //
          // Ook op een televisie, sinds 19-10-2026 (Saber: het lichte thema op de Shield "volledig zoals
          // het is op pc en gsm"). Hij bleef daar weg toen het nog een schermvullend plaatje met een
          // verloopmasker was; nu is het één gebakken beeld en een verloop, zonder tussenlaag.
          //
          // De doorzichtigheid via `Image` en NIET via een `Opacity`-widget. Die laatste zet een
          // schermvullende `saveLayer` op — de duurste soort laag die er is.
          //
          // En het uitdoven ZONDER `ShaderMask`: dat was ook een schermvullende tussenlaag, en op de
          // S26 stond de grafische chip op 99 % met 29 ms per beeld terwijl de cd draaide — zie
          // [hoesUitdoving]. Nu ligt dezelfde was er nog eens overheen, oplopend in dekking; dat
          // geeft hetzelfde beeld en de chip tekent het in één keer.
          if (p.currentCover != null) ...[
            // Sterk vervaagd en één keer gebakken (Saber, 18-10-2026): scherp stond het logo van de
            // hoes ("MADONNA ray of light") groot achter de titel en de tijdbalk. Dezelfde gebakken
            // waas als bovenaan een albumpagina ([HoesAchtergrond]): bij het tekenen kost hij niets,
            // en bij een nieuw nummer blijft de vorige staan tot de volgende klaar is.
            Positioned.fill(
              key: const Key('np-hoes-achter'),
              child: IgnorePointer(
                child: LayoutBuilder(
                  builder: (_, c) => HoesAchtergrond(beeld: MemoryImage(p.currentCover!), hoogte: c.maxHeight),
                ),
              ),
            ),
            Positioned.fill(
              child: IgnorePointer(
                child: AnimatedContainer(
                  duration: kWas,
                  curve: Curves.easeOut,
                  decoration: BoxDecoration(gradient: hoesUitdoving(wasBasis(p.wasKleur))),
                ),
              ),
            ),
          ],
          SafeArea(
              // A television reports no insets, so SafeArea alone is a no-op there; this is the
              // margin that keeps the back arrow off the part of the picture a set cuts away.
              minimum: tvOverscan,
            child: Column(
              children: [
                // Geen chevron op een televisie: 48 punten hoogte voor iets dat de BACK-toets van de
                // afstandsbediening al doet, op een scherm waar elke punt telt.
                if (!isTv)
                  Row(
                    children: [
                      IconButton(
                        icon: const Icon(Icons.keyboard_arrow_down_rounded, size: 30),
                        onPressed: () => Navigator.pop(context),
                      ),
                      // "Speelt op: … ▾" (Saber, 21-10-2026): de zones, en hier verder luisteren vanaf
                      // elke zone.
                      const Expanded(child: Center(child: ZoneKiesKnop())),
                      // Hetzelfde menu als op een albumtegel en een nummerrij, op het enige scherm
                      // waar het niet zat.
                      //
                      // Van "ik hoor dit" naar "laat me de rest van deze artiest zien" was hier
                      // doodlopend: dit scherm sluiten, terug naar waar je vandaan kwam, en zelf
                      // zoeken. Terwijl elke rij in de app dat menu al heeft — met ga naar album,
                      // ga naar artiest, radio, favoriet en de wachtrij erin. Eén knop, geen nieuw
                      // menu: een tweede lijst met dezelfde acties gaat vroeg of laat uiteenlopen.
                      if (t != null)
                        Builder(
                          builder: (knopContext) => TvLabelled(
                            label: 'Meer',
                            child: IconButton(
                              icon: const Icon(Icons.more_horiz_rounded, size: 26),
                              tooltip: 'Meer',
                              onPressed: () =>
                                  _toonItemMenu(knopContext, _metStapelKeuze(_nummerMenu(knopContext, t))),
                            ),
                          ),
                        ),
                    ],
                  ),
                // **Naast elkaar op een breed venster, gestapeld op de rest.**
                //
                // Wat dit oplost: op een venster van 1600 punten stond dit scherm als een kolom van
                // 560 in het midden, met links en rechts samen duizend punten zwart. De hoes werd
                // uit de HOOGTE gerekend en bleef klein terwijl er breedte over was.
                //
                // En de cd is hier het lastige: die schuift naar rechts uit de hoes — precies de
                // kant waar de tekstkolom komt. Zie [hoesNaast]; die deelt door `1 + reisfactor`,
                // en dat is de hele reden dat de plaat niet onder de titel schuift.
                if (naast)
                  Expanded(
                    child: Padding(
                      padding: const EdgeInsets.fromLTRB(kGoot, 0, kGoot, kRuimte32),
                      child: Row(
                        children: [
                          Expanded(
                            child: Row(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                hoesKolom,
                                const SizedBox(width: kSpeelGat),
                                SizedBox(
                                  width: kSpeelKolom,
                                  child: Column(
                                    mainAxisSize: MainAxisSize.min,
                                    crossAxisAlignment: CrossAxisAlignment.start,
                                    children: onder,
                                  ),
                                ),
                              ],
                            ),
                          ),
                          // Het paneel schuift van rechts binnen: zijn vak groeit, en het paneel hangt
                          // aan de linkerkant van dat vak.
                          if (paneelBreedte > 0)
                            SizedBox(
                              width: paneelBreedte,
                              child: ClipRect(
                                child: OverflowBox(
                                  alignment: Alignment.centerLeft,
                                  minWidth: kNuSpeeltWachtrij,
                                  maxWidth: kNuSpeeltWachtrij,
                                  child: Padding(
                                    padding: const EdgeInsets.fromLTRB(kRuimte24, kRuimte8, 0, kRuimte8),
                                    child: GlasVlak(
                                      key: const ValueKey('np-wachtrijpaneel'),
                                      vorm: const BorderRadius.all(Radius.circular(18)),
                                      kleur: _panel,
                                      child: WachtrijPaneelView(
                                        opGlas: true,
                                        onSluit: _wachtrij ? _wisselWachtrij : null,
                                      ),
                                    ),
                                  ),
                                ),
                              ),
                            ),
                        ],
                      ),
                    ),
                  )
                // Dwars: de hoes links op maat van de hoogte, de kolom rechts. De kolom mag als
                // vangnet schuiven — op een nog lagere telefoon blijft de knoppenrij zo bereikbaar,
                // in plaats van onder de rand te verdwijnen zoals vóór 05-10-2026.
                else if (dwars)
                  Expanded(
                    child: Padding(
                      padding: const EdgeInsets.fromLTRB(kGoot, 0, kGoot, kRuimte8),
                      child: Row(
                        key: const Key('np-dwars'),
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          hoesKolom,
                          const SizedBox(width: kLiggendGat),
                          SizedBox(
                            width: kolom,
                            child: Center(
                              child: SingleChildScrollView(
                                child: Column(
                                  mainAxisSize: MainAxisSize.min,
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: onder,
                                ),
                              ),
                            ),
                          ),
                        ],
                      ),
                    ),
                  )
                else ...[
                  const Spacer(),
                  hoesKolom,
                  SizedBox(height: isTv ? 16 : 30),
                  ...onder,
                  // Gestapeld alles een stuk naar boven (Saber, 19-10-2026: "daar hebben we nog vrij
                  // ruimte, pas op niet teveel"): op de gsm een vijfde van de vrije hoogte boven, de rest
                  // eronder — op het voorbeeld de kop 20 punten hoger, de bediening 40. Op een groter
                  // scherm minder ver. Spacers en geen vaste maat: dit blok heeft geen schuifvangnet.
                  Spacer(flex: !gestapeld ? 1 : (isCompact(context) ? 4 : 2)),
                ],
              ],
            ),
          ),
        ],
      )),
      ),
    );
  }

  /// Links en rechts als vorige en volgende — maar alléén vanaf de hoes.
  ///
  /// Overal elders op dit scherm zijn het de pijlen waarmee je tussen de knoppen loopt, en die
  /// mag je niet afnemen: dan is de speakerkeuze niet meer te bereiken en kun je de muziek niet
  /// meer terughalen uit een andere kamer.
  ///
  /// `KeyRepeatEvent` telt niet mee: een pijl ingedrukt houden zou anders door de hele wachtrij
  /// razen. En is er geen volgende (of geen vorige), dan gaat de toets terug naar de markering in
  /// plaats van opgeslokt te worden — een dode toets voelt kapot.
  ///
  /// **Ingedrukt houden spoelt** (Saber, 16-10-2026: "ik wil dit doen met de afstandsbediening door
  /// blijven drukken"), en daarom wisselt het nummer pas bij het loslaten. Zie [SpoelPijlen].
  ///
  /// **Omhoog gaat naar de artiest** (Saber, 17-10-2026: "ja, omhoog vanaf de hoes"): naar het eerste
  /// rondje vóór de artiestnaam, en OK opent dan de artiestpagina. Boven de hoes staat niets, dus deze
  /// pijl deed hier tot nu toe niets.
  KeyEventResult _pijlAlsNummerknop(KeyEvent e, _Transport x) {
    _transportNu = x;
    if (!isTv) return KeyEventResult.ignored;
    // Niet meer op de hoes? Dan mag een loslaten dat nog onderweg is ook niets meer doen.
    if (!_opHoes) {
      _spoelPijlen.vergeet();
      return KeyEventResult.ignored;
    }
    if (e.logicalKey == LogicalKeyboardKey.arrowUp) {
      if (e is KeyDownEvent && _eersteRondje.context != null && _eersteRondje.canRequestFocus) {
        _eersteRondje.requestFocus();
        return KeyEventResult.handled;
      }
      return e is KeyRepeatEvent ? KeyEventResult.handled : KeyEventResult.ignored;
    }
    // In de stapel bladeren links en rechts (Saber, 19-10-2026); vasthouden spoelt dan niet.
    if (_stapel.currentState != null &&
        (e.logicalKey == LogicalKeyboardKey.arrowLeft || e.logicalKey == LogicalKeyboardKey.arrowRight)) {
      if (e is KeyDownEvent) _stapelBesturing.blader(e.logicalKey == LogicalKeyboardKey.arrowRight ? 1 : -1);
      return KeyEventResult.handled;
    }
    return _spoelPijlen.opToets(e);
  }

  /// De speler zoals die bij de laatste toets was: de pijlen lezen hem pas als ze iets doen.
  _Transport? _transportNu;

  late final _spoelPijlen = SpoelPijlen(
    vorige: () => _transportNu?.previous?.call(),
    volgende: () => _transportNu?.next?.call(),
    spoel: (seconden) {
      final x = _transportNu;
      if (x != null && x.canSeek) x.nudge(seconden);
    },
  );
}


/// De sleutel naar de Navigator, zodat "ga naar Nu speelt" van buiten de boom kan.
final appNavigator = GlobalKey<NavigatorState>();

/// Naar "Nu speelt", vanaf waar je ook bent.
///
/// Eén plek, want er waren er twee — allebei in de spelerbalk, en die balk stond op maar twee van
/// de acht pagina's. Vanaf een artiestpagina of een afspeellijst was er dus geen enkele weg.
///
/// Springt terug in plaats van te stapelen: de route krijgt een naam, en staat hij er al, dan
/// popt hij tot daar. Anders zou tweemaal drukken twee schermen op elkaar leggen en moest je ook
/// tweemaal terug.
void naarNuSpeelt(BuildContext context) {
  // De HOOFDnavigator, want daar staat "nu speelt" op. De stapel die hij hieronder afzoekt is die
  // van de hele app; op de binnennavigator zou hij een route zoeken die daar nooit ligt en er dus
  // een tweede naast zetten.
  final nav = Navigator.of(context, rootNavigator: true);
  var bestaat = false;
  nav.popUntil((r) {
    if (r.settings.name == _nuSpeeltRoute) bestaat = true;
    return true; // alleen kijken, niets poppen
  });
  if (bestaat) {
    nav.popUntil((r) => r.settings.name == _nuSpeeltRoute);
    return;
  }
  nav.push(nuSpeeltRoute());
}

const _nuSpeeltRoute = 'nu-speelt';

/// Hoe lang er na een OK op de hoes van Nu speelt op een tweede gewacht wordt. Langer dan de 0,2 s van
/// twee tikken op een scherm: een knop van een afstandsbediening veert trager terug dan een vinger.
const kTvTweedeOk = Duration(milliseconds: 350);

/// Na hoe lang zonder toets een tv vanzelf naar Nu speelt gaat, als er muziek speelt (Saber,
/// 16-10-2026: "Nu speelt schermvullend" — grote hoes, draaiende cd, de kleuren van de hoes; een
/// toets brengt je terug waar je was).
const kTvStilstand = Duration(minutes: 2);

/// De toetsen die bij stilstand gewoon doen wat ze doen, in plaats van Nu speelt te sluiten.
final kMediatoetsen = <LogicalKeyboardKey>{
  LogicalKeyboardKey.mediaPlayPause, LogicalKeyboardKey.mediaPlay, LogicalKeyboardKey.mediaPause,
  LogicalKeyboardKey.mediaTrackNext, LogicalKeyboardKey.mediaTrackPrevious, LogicalKeyboardKey.mediaFastForward,
  LogicalKeyboardKey.mediaRewind, LogicalKeyboardKey.mediaStop, LogicalKeyboardKey.audioVolumeUp,
  LogicalKeyboardKey.audioVolumeDown, LogicalKeyboardKey.audioVolumeMute,
};

/// Moet de tv nu naar Nu speelt? Alleen als er [kTvStilstand] lang niets ingedrukt is, er muziek
/// speelt, en er niets over de pagina ligt ([bovenaan]: geen menu, geen dialoog, niet al Nu speelt).
bool naarNuSpeeltNaStilstand({required Duration stil, required bool speelt, required bool bovenaan}) =>
    speelt && bovenaan && stil >= kTvStilstand;

/// Het nu-speelt-scherm, van onderen.
///
/// **Waarom niet gewoon een MaterialPageRoute.** Die schuift van rechts in, terwijl de sluitknop van
/// dat scherm een pijl naar BENEDEN is. Die twee spraken elkaar tegen: de knop belooft een beweging
/// die de route niet maakt, en er was geen enkel gebaar om het scherm weg te vegen — terwijl dat de
/// gebarentaal is die iedereen van een muziekapp kent.
///
/// 320 ms met easeOutCubic: lang genoeg om te zien dat het één beweging is, kort genoeg om niet in
/// de weg te zitten als je het scherm tien keer per rit opent.
///
/// **Ondoorzichtig, en dat is de warmte.** Saber op 08-10-2026: *"ik teste gisteren de app op de
/// ipad en die werd enorm heet bij de now playing screen"*. Deze route stond op `opaque: false`,
/// "zodat het scherm eronder blijft staan terwijl dit omhoog schuift". Maar daarvoor hoeft dat niet:
/// een route zet zijn ondoorzichtigheid pas aan als de overgang klaar is, en tijdens het schuiven
/// (open en dicht) staat het scherm eronder er hoe dan ook. Doorzichtig betekende alleen dat het
/// hele scherm eronder — startpagina, glazen bovenbalk, de hoezen — bij ELK beeld van de draaiende
/// cd opnieuw getekend werd, onzichtbaar achter dit scherm, en dat zijn animaties (de glans van de
/// laadtegels) doorliepen op het schermritme. Op een telefoon viel dat mee: daar staat de vervaging
/// van het glas uit (`zonderBlur: isCompact`). Op de iPad, met 120 Hz, meer pixels en echt glas, niet.
///
/// [scherm] alleen voor de toets (nu_speelt_ondoorzichtig_test.dart): het echte scherm heeft libmpv.
Route<void> nuSpeeltRoute({WidgetBuilder? scherm}) => PageRouteBuilder<void>(
      settings: const RouteSettings(name: _nuSpeeltRoute),
      transitionDuration: const Duration(milliseconds: 320),
      reverseTransitionDuration: const Duration(milliseconds: 260),
      opaque: true,
      barrierColor: Colors.transparent,
      pageBuilder: (context, __, ___) => scherm?.call(context) ?? const NowPlayingScreen(),
      transitionsBuilder: (_, animatie, __, kind) => SlideTransition(
        position: Tween(begin: const Offset(0, 1), end: Offset.zero)
            .animate(CurvedAnimation(parent: animatie, curve: Curves.easeOutCubic)),
        child: kind,
      ),
    );

/// Wat de sneltoets vraagt.
class NaarNuSpeeltIntent extends Intent {
  const NaarNuSpeeltIntent();
}

/// "Hier verder luisteren" op de pc: hij houdt de stand zelf bij (zie verder_luisteren.dart).
class _PcVerderBron implements VerderBron {
  _PcVerderBron(this.sharing, this.player);

  final LanSharing sharing;
  final PlayerStore player;

  @override
  String get mijnId => sharing.mijnId;

  @override
  bool get ikSpeel => player.speeltErgens;

  @override
  Track? nummer(String id) => sharing.nummerVoorId(id);

  @override
  Future<({Map<String, dynamic>? stand, Map<String, dynamic>? verzoek})?> haal() async =>
      (stand: sharing.state.progress.toJson(), verzoek: sharing.state.verzoek);

  @override
  Future<void> speel(List<Track> rij, int index, Duration positie,
          {required bool spelen, required bool shuffle, required RepeatMode herhaal, String? radioArtiest}) =>
      _verderSpelen(player, rij, index, positie,
          spelen: spelen, shuffle: shuffle, herhaal: herhaal, radioArtiest: radioArtiest);

  @override
  void pauzeer() => player.pauzeer();
}

/// "Hier verder luisteren" op een gsm, iPad, Mac of Shield: vraagt de stand aan de pc.
class _ToestelVerderBron implements VerderBron {
  _ToestelVerderBron(this.library, this.player, this.mijnId);

  final LibraryStore library;
  final PlayerStore player;

  @override
  final String mijnId;

  @override
  bool get ikSpeel => player.speeltErgens;

  /// Welke revisie van de gedeelde staat dit toestel kent: dan stuurt de pc alleen de stand mee.
  int? _rev;

  final Map<String, Track> _nummers = {};
  int _idsVoor = -1;

  @override
  Track? nummer(String id) {
    final tracks = library.tracks;
    if (_idsVoor != tracks.length) {
      _idsVoor = tracks.length;
      _nummers
        ..clear()
        ..addEntries([
          for (final t in tracks)
            if (library.gedeeldId(t.path) case final i?) MapEntry(i, t),
        ]);
    }
    return _nummers[id];
  }

  @override
  Future<({Map<String, dynamic>? stand, Map<String, dynamic>? verzoek})?> haal() async {
    final c = library.remote;
    if (c == null) return null;
    final s = await c.speelstand(sinds: _rev, toestel: mijnId, naam: deviceName());
    _rev = (s['rev'] as num?)?.toInt() ?? _rev;
    return (
      stand: (s['progress'] as Map?)?.cast<String, dynamic>(),
      verzoek: (s['verzoek'] as Map?)?.cast<String, dynamic>(),
    );
  }

  @override
  Future<void> speel(List<Track> rij, int index, Duration positie,
          {required bool spelen, required bool shuffle, required RepeatMode herhaal, String? radioArtiest}) =>
      _verderSpelen(player, rij, index, positie,
          spelen: spelen, shuffle: shuffle, herhaal: herhaal, radioArtiest: radioArtiest);

  @override
  void pauzeer() => player.pauzeer();
}

/// Overnemen wat een ander toestel speelde: de wachtrij op zijn plek, of een radio rond dezelfde artiest
/// met het nummer dat speelde als eerste, op dezelfde plek (Saber, 17-10-2026: "ook de radio").
Future<void> _verderSpelen(PlayerStore player, List<Track> rij, int index, Duration positie,
    {required bool spelen, required bool shuffle, required RepeatMode herhaal, String? radioArtiest}) async {
  final ctx = appNavigator.currentContext;
  if (radioArtiest == null || ctx == null || rij.isEmpty) {
    return player.neemOver(rij, index, positie, spelen: spelen, shuffle: shuffle, herhaal: herhaal);
  }
  final zaad = rij[index.clamp(0, rij.length - 1)];
  await startRadio(ctx, radioArtiest, zaad: zaad, hier: true);
  // Het zaad klinkt als eerste; zodra libmpv het kent, naar de plek waar het andere toestel was.
  for (var i = 0; i < 60; i++) {
    if (player.current?.path == zaad.path && player.duration > Duration.zero) break;
    await Future<void>.delayed(const Duration(milliseconds: 100));
  }
  if (player.current?.path == zaad.path && positie > const Duration(seconds: 1)) player.seek(positie);
}

/// De balk "Hier verder luisteren" (Saber, 17-10-2026): speelt er op een ander toestel iets, of
/// speelde er kort geleden iets, dan biedt hij aan om hier verder te gaan. Zie verder_luisteren.dart.
class VerderBalk extends StatelessWidget {
  const VerderBalk({super.key});

  @override
  Widget build(BuildContext context) {
    final v = context.watch<VerderLuisteren>();
    final a = v.aanbod;
    return AnimatedSwitcher(
      duration: const Duration(milliseconds: 260),
      switchInCurve: Curves.easeOutCubic,
      transitionBuilder: (kind, anim) => FadeTransition(
        opacity: anim,
        child: SlideTransition(
          position: Tween(begin: const Offset(0, .35), end: Offset.zero).animate(anim),
          child: kind,
        ),
      ),
      child: a == null ? const SizedBox.shrink(key: ValueKey('verder-geen')) : _kaart(context, v, a),
    );
  }

  Widget _kaart(BuildContext context, VerderLuisteren v, VerderAanbod a) {
    final t = a.nummer;
    // Meeluisteren en niet één keer lezen: op een toestel komen de hoezen via een ronde van de pc
    // binnen, en de balk staat er vaak al eerder. Met `read` bleef hij leeg (S26, 18-10-2026).
    final hoes = context.select<LibraryStore, Uint8List?>((l) => l.coverForTrack(t));
    // Op een telefoon een rond knopje: met "Verder luisteren" erop bleef er van de titel "Skinn…"
    // over (S26, 18-10-2026).
    final smal = isCompact(context);
    final waar = a.toestelNaam.isEmpty ? 'een ander toestel' : a.toestelNaam;
    final kop = a.radioArtiest != null
        ? (a.speelde ? 'Radio op $waar' : 'Verder met de radio · op $waar')
        : (a.speelde ? 'Speelt op $waar' : 'Verder waar je was · op $waar');
    final knop = a.speelde ? 'Hier verder luisteren' : 'Verder luisteren';
    return ConstrainedBox(
      key: ValueKey('verder-${a.sleutel}'),
      constraints: const BoxConstraints(maxWidth: 600),
      child: GlasVlak(
        vorm: const BorderRadius.all(Radius.circular(18)),
        kleur: _panel,
        balk: true,
        // In een blad over de balken heen: die worden zolang dicht (nooit glas op glas).
        bovenop: true,
        child: Padding(
          padding: const EdgeInsets.fromLTRB(10, 10, 6, 10),
          child: Row(
            children: [
              cover(hoes, size: 46, radius: 8),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(kop, maxLines: 1, overflow: TextOverflow.ellipsis,
                        style: TextStyle(color: _accent2, fontSize: 11.5, fontWeight: FontWeight.w600)),
                    const SizedBox(height: 2),
                    Text('${t.title} — ${t.artist}',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(fontSize: 13.5, fontWeight: FontWeight.w600)),
                    Text(_fmt(startPositie(a, DateTime.now().millisecondsSinceEpoch)),
                        style: TextStyle(color: _muted, fontSize: 11.5)),
                  ],
                ),
              ),
              const SizedBox(width: 8),
              // Glas met paarse tekst, zoals elke knop in de app: geen paars gevuld vlak.
              if (smal)
                GlasKnop.rond(
                  key: const ValueKey('verder-knop'),
                  icoon: Icons.play_arrow_rounded,
                  tooltip: knop,
                  onPressed: () => v.neemOver(),
                )
              else
                GlasKnop(
                  key: const ValueKey('verder-knop'),
                  icoon: Icons.play_arrow_rounded,
                  label: knop,
                  autofocus: isTv,
                  onPressed: () => v.neemOver(),
                ),
              TvLabelled(
                label: 'Niet nu',
                child: IconButton(
                  key: const ValueKey('verder-weg'),
                  tooltip: 'Niet nu',
                  icon: const Icon(Icons.close_rounded, size: 18),
                  color: _muted,
                  onPressed: v.wijsAf,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

/// "Verder op …" in de spelerbalk (Saber, 18-10-2026).
///
/// De balk boven de inhoud stoorde ("het zit echt op een slechte plaats"), en wie hem wegklikte kon
/// er niet meer bij. Hier bedekt hij niets en blijft hij staan zolang er een aanbod is: hij gaat weg
/// als je overneemt of als het aanbod verloopt ([kVerderTotEenDag]).
///
/// - Op een breed scherm (pc, Mac, iPad, tv): een glazen knopje rechts in de balk met het toestel en
///   het nummer. Eén klik of OK neemt over.
/// - Op een telefoon ([smal]): een icoon met een stipje; tikken toont het aanbod als blad, met
///   "Niet nu" ([VerderBalk]).
class VerderKnop extends StatelessWidget {
  const VerderKnop({super.key, this.smal = false});

  final bool smal;

  @override
  Widget build(BuildContext context) {
    final v = context.watch<VerderLuisteren>();
    // Het icoontje van de telefoon wijkt voor de zoneknop ernaast: daar staat "Hier verder" ook in, en
    // die krijgt het stipje (Saber, 21-10-2026: twee keer bijna hetzelfde icoon).
    final a = smal && (_misschien<ZoneLijst>(context, luister: true)?.ondersteund ?? false) ? null : v.aanbod;
    return AnimatedSwitcher(
      duration: const Duration(milliseconds: 220),
      switchInCurve: Curves.easeOutCubic,
      child: a == null
          ? const SizedBox.shrink(key: ValueKey('verder-geen'))
          : smal
              ? _icoon(context, a)
              : _knop(context, v, a),
    );
  }

  static String _waar(VerderAanbod a) => a.toestelNaam.isEmpty ? 'een ander toestel' : a.toestelNaam;

  Widget _icoon(BuildContext context, VerderAanbod a) => IconButton(
        key: ValueKey('verder-icoon-${a.sleutel}'),
        tooltip: 'Verder van ${_waar(a)}',
        onPressed: () => showModalBottomSheet<void>(
          context: context,
          backgroundColor: Colors.transparent,
          builder: (_) => const _VerderBlad(),
        ),
        icon: Stack(clipBehavior: Clip.none, children: [
          Icon(Icons.devices_rounded, size: 22, color: _muted),
          Positioned(
            right: -2,
            top: -2,
            child: Container(
              width: 8,
              height: 8,
              decoration: BoxDecoration(color: _accent2, shape: BoxShape.circle),
            ),
          ),
        ]),
      );

  Widget _knop(BuildContext context, VerderLuisteren v, VerderAanbod a) {
    final t = a.nummer;
    final kop = a.speelde ? 'Speelt op ${_waar(a)}' : 'Verder op ${_waar(a)}';
    final tijd = _fmt(startPositie(a, DateTime.now().millisecondsSinceEpoch));
    return Tooltip(
      key: ValueKey('verder-knop-${a.sleutel}'),
      message: a.speelde ? 'Hier verder luisteren' : 'Verder luisteren',
      child: Pressable(
        key: const ValueKey('verder-knop'),
        onPressed: () => v.neemOver(),
        borderRadius: BorderRadius.circular(999),
        scaleOnFocus: false,
        vastePlek: false,
        child: GlasVlak(
          vorm: const BorderRadius.all(Radius.circular(999)),
          kleur: _panel,
          balk: true,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(10, 6, 14, 6),
            child: Row(mainAxisSize: MainAxisSize.min, children: [
              Icon(Icons.devices_rounded, size: 18, color: _accent2),
              const SizedBox(width: 8),
              Flexible(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(kop,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(color: _accent2, fontSize: 11, fontWeight: FontWeight.w600)),
                    Text('${t.title} · $tijd',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: TextStyle(color: MenuTint.nu.tekst, fontSize: 12.5, fontWeight: FontWeight.w600)),
                  ],
                ),
              ),
            ]),
          ),
        ),
      ),
    );
  }
}

/// Het blad van de telefoon: het aanbod met "Verder luisteren" en "Niet nu". Gaat vanzelf dicht als
/// er geen aanbod meer is (overgenomen of weggeklikt).
class _VerderBlad extends StatelessWidget {
  const _VerderBlad();

  @override
  Widget build(BuildContext context) {
    final a = context.watch<VerderLuisteren>().aanbod;
    if (a == null) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (context.mounted) Navigator.of(context).maybePop();
      });
    }
    return const SafeArea(
      child: Padding(padding: EdgeInsets.fromLTRB(12, 0, 12, 12), child: VerderBalk()),
    );
  }
}

