  Widget _browseResults() {
    final leeg = _artists.isEmpty && _albumHits.isEmpty && _trackHits.isEmpty;
    // Het draaiwiel alleen zolang er nog NIETS te tonen is. Hier stond `if (_browseBusy)`, en
    // [_browseBusy] gaat pas uit als ook Discogs en MusicBrainz klaar zijn — die vullen ná Deezer aan,
    // MusicBrainz één vraag per 1,1 s. Zo hield het scherm de snelle uitslag toch gegijzeld door de
    // trage, precies wat [_addMusicBrainzHits] zegt te vermijden. Gemeten op 21-10-2026 op de gsm
    // ("Tate McRae Revolving door"): de drie Deezer-lijsten na 451 ms (deezer.log), op het scherm na
    // 4,2–4,6 s.
    if (_browseBusy && leeg) return Center(child: CircularProgressIndicator(color: _accent));
    if (leeg) {
      return Center(
        child: Padding(
          padding: EdgeInsets.all(24),
          child: Text('Zoek een artiest, album of nummer — bronnen (torrent/Soulseek) verschijnen eronder.',
              textAlign: TextAlign.center, style: TextStyle(color: _muted)),
        ),
      );
    }
    return ListView(
      // Waar je gebleven was blijft staan als je even naar de speler gaat. De route eronder
      // overleeft de sectiewissel, dus die bewaart de scrolstand — zelfde truc als bij het
      // albumraster en de nummerlijst.
      key: const PageStorageKey('online-bladeren'),
      padding: onderOp(context, const EdgeInsets.only(bottom: 24)),
      children: [
        // Discogs en MusicBrainz vullen nog aan: een dun streepje boven wat er al staat. Altijd twee
        // pixels hoog, zodat de lijst niet verspringt als het verdwijnt.
        SizedBox(
          height: 2,
          child: _browseBusy
              ? LinearProgressIndicator(minHeight: 2, color: _accent, backgroundColor: Colors.transparent)
              : null,
        ),
        if (_artists.isNotEmpty) ...[
          _browseHeader('Artiesten', _artists.length),
          SizedBox(
            height: 158,
            child: ListView.separated(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(horizontal: 20),
              itemCount: _artists.length,
              separatorBuilder: (_, __) => const SizedBox(width: 12),
              itemBuilder: (_, i) {
                final a = _artists[i];
                return InkWell(
                  onTap: () =>
                      openPagina(context, (_) => ArtistBrowsePage(a)),
                  borderRadius: BorderRadius.circular(12),
                  child: SizedBox(
                    width: 116,
                    child: Column(
                      children: [
                        // Dezelfde vorm als het artiestenraster, maar de foto van precies deze
                        // gevonden artiest (Deezer): op naam zoeken bij TheAudioDB kan hier een
                        // naamgenoot opleveren. Alleen van MusicBrainz (geen Deezer-foto): op zijn
                        // MusicBrainz-nummer bij TheAudioDB, Discogs of Wikipedia — [MbArtiestFoto].
                        if (a.picture == null && (a.origin?.isMb ?? false))
                          Builder(builder: (context) {
                            final discogs = DiscogsService(context.read<AppSettings>());
                            return FutureBuilder<String?>(
                              key: ValueKey('mbfoto-${a.origin!.id}'),
                              future: MbArtiestFoto.voor(a.origin!.id, context.read<MusicBrainzService>(),
                                  discogs: discogs),
                              builder: (_, s) => _netCover(s.data,
                                  size: 116,
                                  radius: kArtiestHoek,
                                  // Een Discogs-plaatje vraagt de sleutel; elders gaat die niet heen.
                                  headers: s.data == null ? null : discogs.beeldKoppen(s.data!)),
                            );
                          })
                        else
                          _netCover(a.picture, size: 116, radius: kArtiestHoek),
                        const SizedBox(height: 6),
                        Text(a.name,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            textAlign: TextAlign.center,
                            style: kTegelTitel),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
        ],
        if (_albumHits.isNotEmpty) ...[
          _browseHeader('Albums', _albumHits.length),
          SizedBox(
            height: 186,
            child: ListView.separated(
              scrollDirection: Axis.horizontal,
              padding: const EdgeInsets.symmetric(horizontal: 20),
              itemCount: _albumHits.length,
              separatorBuilder: (_, __) => const SizedBox(width: 12),
              itemBuilder: (_, i) {
                final h = _albumHits[i];
                return InkWell(
                  onTap: () => openPagina(context, (_) => AlbumBrowsePage(h.artist, h.album)),
                  borderRadius: BorderRadius.circular(12),
                  child: SizedBox(
                    width: 132,
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        // Schaduw en spiegeling zoals elke albumtegel (Saber, 19-10-2026).
                        TegelLicht(
                          maat: 132,
                          hoek: 10,
                          spiegel: spiegelVanUrl(h.album.cover),
                          child: _netCover(h.album.cover, size: 132, radius: 10),
                        ),
                        const SizedBox(height: 6),
                        Text(h.album.title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: kTegelTitel),
                        _maybeFocusable(Align(
                          alignment: Alignment.centerLeft,
                          child: ArtistNames(names: [h.artist], style: kTegelOnder),
                        )),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
        ],
        if (_trackHits.isNotEmpty) ...[
          _browseHeader('Nummers', _trackHits.length),
          ..._trackHits.asMap().entries.map((e) => _browseTrackRow(e.key, e.value)),
        ],
      ],
    );
  }

  Widget _browseHeader(String title, int count) => Padding(
        padding: const EdgeInsets.fromLTRB(24, 14, 24, 8),
        child: Text('${title.toUpperCase()}  ·  $count', style: kOpschrift),
      );

  Widget _browseTrackRow(int i, CatalogTrackHit t) {
    final open = _trackExpanded == i;
    return Column(
      children: [
        InkWell(
          onTap: () => setState(() => _trackExpanded = open ? null : i),
          child: Container(
            margin: const EdgeInsets.symmetric(horizontal: 20, vertical: 1),
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 9),
            decoration:
                BoxDecoration(color: open ? _panel : Colors.transparent, borderRadius: BorderRadius.circular(8)),
            child: Row(
              children: [
                _netCover(t.cover, size: 42, radius: 6),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(t.title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: kTekstNormaal),
                      _artistLine(splitFeatured(t.artist, t.title), kTekstKlein),
                    ],
                  ),
                ),
                // Dezelfde knop als bij elk nummer op een albumpagina: zoekt zelf de beste bron en haalt
                // hem (Saber, 20-10-2026: "zo kan ik snel een losse song zoeken en downloaden"). Een tik
                // op de rij opent nog steeds de bronnen om zelf te kiezen.
                if (context.read<LibraryStore>().ownedTrack(t.artist, t.title) != null)
                  Tooltip(
                    message: 'Al in je bibliotheek',
                    child: Icon(Icons.library_add_check_rounded, color: _accent2),
                  )
                else ...[
                  SpeelNuKnop(artiest: t.artist, titel: t.title, seconden: t.seconden, album: t.album, hoes: t.cover),
                  _downloadControl(context,
                      jobKey: _zoekSleutel(t), onDownload: () => _downloadHit(t), tooltip: 'Downloaden (beste bron)'),
                ],
